function isFullBleedScreen(screen: Screen) {
  return (
    screen === 'assetWarmup' ||
    screen === 'versus' ||
    screen === 'arcadeTransition' ||
    screen === 'miniGame' ||
    screen === 'miniGameResult' ||
    screen === 'arcadeGameOver' ||
    screen === 'unlockReveal' ||
    screen === 'customRooms' ||
    screen === 'tournamentBracket' ||
    screen === 'tournamentAdvancement'
  );
}

