function SettingsScreen({
  mode,
  setMode,
  cpuDifficulty,
  setCpuDifficulty,
  settings,
  setSettings,
  inputPromptMode,
  onInputPromptModeChange,
  onlineProfile,
  onOnlineProfileChange,
  selectedStageName,
  selectedStageBgmTitle,
  menuBgmTrackTitle,
  menuBgmTrackCount,
  onMenuBgmTrackChange,
  onOptionsShortcut,
  onOpenStarterGuide,
  onMemoryCardLoaded,
  onBack,
  onAnalytics
}: {
  mode: MatchMode;
  setMode: (mode: MatchMode) => void;
  cpuDifficulty: CpuDifficulty;
  setCpuDifficulty: (difficulty: CpuDifficulty) => void;
  settings: GameSettings;
  setSettings: Dispatch<SetStateAction<GameSettings>>;
  inputPromptMode: InputPromptMode;
  onInputPromptModeChange: (mode: InputPromptMode) => void;
  onlineProfile: OnlinePlayerProfile | null;
  onOnlineProfileChange: (profile: Partial<OnlinePlayerProfile>) => void;
  selectedStageName: string;
  selectedStageBgmTitle: string;
  menuBgmTrackTitle: string;
  menuBgmTrackCount: number;
  onMenuBgmTrackChange: (index: number) => void;
  onOptionsShortcut: () => void;
  onOpenStarterGuide: () => void;
  onMemoryCardLoaded: () => void;
  onBack: () => void;
  onAnalytics: AnalyticsCapture;
}) {
  const [activeTab, setActiveTab] = useState<SettingsTab>('controls');
  const [activePlayer, setActivePlayer] = useState<1 | 2>(1);
  const [remapRequest, setRemapRequest] = useState<{ player: 1 | 2; action: ActionName } | null>(null);
  const [comboRemapRequest, setComboRemapRequest] = useState<{ player: 1 | 2; comboId: ButtonComboId } | null>(null);
  const [duplicateRequest, setDuplicateRequest] = useState<{ key: string; owner: string } | null>(null);
  const [inputTest, setInputTest] = useState('Press a key to test bindings');
  const [activeSections, setActiveSections] = useState<Record<SettingsTab, number>>({ game: 0, controls: 0, camera: 0, display: 0, audio: 0, console: 0 });
  const selectedCursor = getKoreCursorOption(settings.display.cursorId);
  const [cursorStyleFilter, setCursorStyleFilter] = useState<KoreCursorStyle>(selectedCursor.style);
  const [cursorScaleFilter, setCursorScaleFilter] = useState<KoreCursorScale>(selectedCursor.scale);
  const editorRef = useRef<HTMLElement | null>(null);
  const previousSettingsRef = useRef(settings);
  const activeSectionIndex = Math.min(activeSections[activeTab] ?? 0, sidebars[activeTab].length - 1);
  const tabPrompts = getTabShortcutPrompts(inputPromptMode);
  const visibleCursorOptions = useMemo(
    () => KORE_CURSOR_OPTIONS.filter((cursor) => cursor.style === cursorStyleFilter && cursor.scale === cursorScaleFilter),
    [cursorScaleFilter, cursorStyleFilter]
  );

  const updateSettings = (recipe: (current: GameSettings) => GameSettings) => {
    setSettings((current) => sanitizeGameSettings(recipe(cloneSettings(current))));
  };

  useEffect(() => {
    const previous = previousSettingsRef.current;
    if (previous === settings) return;
    collectTrackedSettingChanges(previous, settings).forEach((change) => {
      onAnalytics('setting_changed', change);
    });
    previousSettingsRef.current = settings;
  }, [onAnalytics, settings]);

  const selectCursorScale = (scale: KoreCursorScale) => {
    setCursorScaleFilter(scale);
    const nextCursorId = `${selectedCursor.style}/${scale}/${selectedCursor.name}.png`;
    if (nextCursorId === selectedCursor.id || !isKoreCursorId(nextCursorId)) return;
    updateSettings((current) => ({ ...current, display: { ...current.display, cursorId: nextCursorId } }));
  };

  useEffect(() => {
    setCursorStyleFilter(selectedCursor.style);
    setCursorScaleFilter(selectedCursor.scale);
  }, [selectedCursor.id, selectedCursor.scale, selectedCursor.style]);

  const cycleOptionsTab = useCallback((direction: -1 | 1) => {
    setActiveTab((current) => {
      const currentIndex = settingsTabs.indexOf(current);
      const nextTab = settingsTabs[(currentIndex + direction + settingsTabs.length) % settingsTabs.length] ?? current;
      if (nextTab !== current) onAnalytics('navigation_clicked', { source: 'settings_tab_shortcut', destination: nextTab });
      return nextTab;
    });
  }, [onAnalytics]);

  useEffect(() => {
    const onControllerTabCycle = (event: Event) => {
      const direction = (event as CustomEvent<{ direction?: -1 | 1 }>).detail?.direction;
      if (direction !== -1 && direction !== 1) return;
      cycleOptionsTab(direction);
      onOptionsShortcut();
    };
    window.addEventListener(SETTINGS_TAB_CYCLE_EVENT, onControllerTabCycle);
    return () => window.removeEventListener(SETTINGS_TAB_CYCLE_EVENT, onControllerTabCycle);
  }, [cycleOptionsTab, onOptionsShortcut]);

  const scrollOptionsSectionIntoView = useCallback((index: number) => {
    window.requestAnimationFrame(() => {
      editorRef.current
        ?.querySelector<HTMLElement>(`[data-section-index="${index}"]`)
        ?.scrollIntoView({ behavior: settings.display.reducedMotion ? 'auto' : 'smooth', block: 'start' });
    });
  }, [settings.display.reducedMotion]);

  const selectSidebarSection = useCallback((index: number) => {
    setActiveSections((current) => ({ ...current, [activeTab]: index }));
    onAnalytics('navigation_clicked', {
      source: 'settings_section',
      settings_tab: activeTab,
      section_index: index,
      section: sidebars[activeTab][index] ?? ''
    });
    scrollOptionsSectionIntoView(index);
  }, [activeTab, onAnalytics, scrollOptionsSectionIntoView]);

  useEffect(() => {
    scrollOptionsSectionIntoView(activeSectionIndex);
  }, [activeSectionIndex, activeTab, scrollOptionsSectionIntoView]);

  useEffect(() => {
    if (!remapRequest && !comboRemapRequest) return;
    const onKeyDown = (event: KeyboardEvent) => {
      if (event.metaKey || event.ctrlKey || event.altKey) return;
      event.preventDefault();
      event.stopPropagation();
      const nextKey = event.code || event.key;
      const target = remapRequest ?? comboRemapRequest;
      if (!target) return;
      const duplicate = findDuplicateKeyboardBinding(settings, nextKey, target);
      if (duplicate && (duplicateRequest?.key !== nextKey || duplicateRequest.owner !== duplicate.owner)) {
        setDuplicateRequest({ key: nextKey, owner: duplicate.owner });
        return;
      }
      if ('comboId' in target) {
        updateSettings((current) => setKeyboardComboBinding(current, target.player, target.comboId, nextKey));
        setInputTest(`P${target.player} ${formatButtonComboLabel(target.comboId, settings.game.controlScheme)} = ${formatKeyName(nextKey)}`);
      } else {
        updateSettings((current) => setKeyboardBinding(current, target.player, target.action, nextKey));
        setInputTest(`P${target.player} ${formatActionLabel(target.action, settings.game.controlScheme)} = ${formatKeyName(nextKey)}`);
      }
      setRemapRequest(null);
      setComboRemapRequest(null);
      setDuplicateRequest(null);
    };
    window.addEventListener('keydown', onKeyDown, true);
    return () => window.removeEventListener('keydown', onKeyDown, true);
  }, [comboRemapRequest, duplicateRequest, remapRequest, settings]);

  useEffect(() => {
    if (remapRequest || comboRemapRequest) return;
    const onKeyDown = (event: KeyboardEvent) => {
      const target = event.target as HTMLElement | null;
      if (target?.isContentEditable || ['INPUT', 'SELECT', 'TEXTAREA'].includes(target?.tagName ?? '')) return;
      if (event.metaKey || event.ctrlKey || event.altKey || event.repeat) return;
      const key = event.key.toLowerCase();
      if (key === 'o' || key === 'p') {
        event.preventDefault();
        onInputPromptModeChange('keyboardShortcut');
        cycleOptionsTab(key === 'p' ? 1 : -1);
        onOptionsShortcut();
        return;
      }
      const bindings = getKeyboardBindingsForEvent(event, mode, settings.controls);
      setInputTest(bindings.length > 0 ? bindings.map((binding) => `P${binding.player} ${formatActionLabel(binding.action, settings.game.controlScheme)}`).join(' / ') : `Unbound: ${formatKeyName(event.code || event.key)}`);
    };
    window.addEventListener('keydown', onKeyDown, true);
    return () => window.removeEventListener('keydown', onKeyDown, true);
  }, [comboRemapRequest, cycleOptionsTab, mode, onInputPromptModeChange, onOptionsShortcut, remapRequest, settings.controls, settings.game.controlScheme]);

  const renderEditor = () => {
    if (activeTab === 'game') {
      const usesOnlineStandardRules = mode === 'online' || mode === 'ranked' || mode === 'private' || mode === 'custom';
      const visibleRoundTimer = usesOnlineStandardRules ? 60 : settings.game.roundTimer;
      const visibleMaxHealth = usesOnlineStandardRules ? defaultGameSettings.game.maxHealth : settings.game.maxHealth;
      return (
        <div className="settings-section-stack">
          <SettingsSection index={0} title="Match Rules" active={activeSectionIndex === 0}>
            <SettingRow label="Match Mode" value={modeLabel(mode)}>
              <CharacterSelectModeCarousel value={mode} setValue={setMode} />
            </SettingRow>
            <SettingRow label="Round Timer" value={formatRoundTimer(visibleRoundTimer)}>
              <RoundTimerControl
                value={visibleRoundTimer}
                setValue={(roundTimer) => {
                  if (!usesOnlineStandardRules) {
                    updateSettings((current) => ({ ...current, game: { ...current.game, roundTimer } }));
                  }
                }}
              />
            </SettingRow>
            <SettingRow label="Max HP" value={usesOnlineStandardRules ? 'Online Standard' : formatMaxHealth(visibleMaxHealth)}>
              <MaxHealthControl
                value={visibleMaxHealth}
                setValue={(maxHealth) => {
                  if (!usesOnlineStandardRules) {
                    updateSettings((current) => ({ ...current, game: { ...current.game, maxHealth } }));
                  }
                }}
              />
            </SettingRow>
            {usesCpuDifficulty(mode) && (
              <SettingRow label="CPU Difficulty" value={cpuDifficultyLabels[cpuDifficulty]}>
                <CpuDifficultyControl value={cpuDifficulty} setValue={setCpuDifficulty} compact />
              </SettingRow>
            )}
          </SettingsSection>
          <SettingsSection index={1} title="Player Profile" active={activeSectionIndex === 1}>
            <SettingRow label="Saved Name" value={onlineProfile?.displayName ?? 'Not set'}>
              <span className="setting-readout">{onlineProfile?.displayName ?? 'Not set'}</span>
            </SettingRow>
            <ArcadeNameCard profile={onlineProfile} onProfileChange={onOnlineProfileChange} />
            <PlayerIdCard profile={onlineProfile} />
            <SettingRow label="Reminder Email" value={sanitizeEmail(onlineProfile?.email) || 'Not set'}>
              <span className="setting-readout">{sanitizeEmail(onlineProfile?.email) || 'Not set'}</span>
            </SettingRow>
            <TournamentEmailSettingsCard profile={onlineProfile} onProfileChange={onOnlineProfileChange} />
          </SettingsSection>
          <SettingsSection index={2} title="Training" active={activeSectionIndex === 2}>
            <SettingToggle label="Training Infinite Health" checked={settings.game.trainingInfiniteHealth} onChange={(checked) => updateSettings((current) => ({ ...current, game: { ...current.game, trainingInfiniteHealth: checked } }))} />
            <SettingToggle label="Frame Advantage Numbers" checked={settings.training.frameAdvantageNumbers} onChange={(checked) => updateSettings((current) => ({ ...current, training: { ...current.training, frameAdvantageNumbers: checked } }))} />
            <SettingToggle label="Block After First Hit" checked={settings.training.blockAfterFirstHit} onChange={(checked) => updateSettings((current) => ({ ...current, training: { ...current.training, blockAfterFirstHit: checked } }))} />
            <SettingToggle label="Auto-Attack" checked={settings.training.autoAttack} onChange={(checked) => updateSettings((current) => ({ ...current, training: { ...current.training, autoAttack: checked } }))} />
            {settings.training.autoAttack && (
              <SettingRow label="Auto-Attack Difficulty" value={cpuDifficultyLabels[settings.training.autoAttackDifficulty]}>
                <CpuDifficultyControl
                  value={settings.training.autoAttackDifficulty}
                  setValue={(autoAttackDifficulty) => updateSettings((current) => ({ ...current, training: { ...current.training, autoAttackDifficulty } }))}
                  compact
                />
              </SettingRow>
            )}
          </SettingsSection>
          <SettingsSection index={3} title="Assist" active={activeSectionIndex === 3}>
            <SettingToggle label="Input Assist" checked={settings.game.inputAssist} onChange={(checked) => updateSettings((current) => ({ ...current, game: { ...current.game, inputAssist: checked } }))} />
          </SettingsSection>
          <SettingsSection index={4} title="Performance" active={activeSectionIndex === 4}>
            <SettingToggle
              label="Auto Detect Menu Lag"
              checked={settings.performance.autoDetectMenuLag}
              onChange={(checked) => updateSettings((current) => ({ ...current, performance: { ...current.performance, autoDetectMenuLag: checked } }))}
            />
            <SettingRow label="Main Menu Fight" value={settings.performance.menuAttractMode === 'snappy' ? 'SNAPPY' : 'FULL'}>
              <PerformanceModeSegmented<MenuAttractPerformanceMode>
                value={settings.performance.menuAttractMode}
                options={[
                  { value: 'full', label: 'Full' },
                  { value: 'snappy', label: 'Snappy' }
                ]}
                onChange={(menuAttractMode) => updateSettings((current) => ({ ...current, performance: { ...current.performance, menuAttractMode } }))}
              />
            </SettingRow>
            <SettingRow label="Menu Motion" value={settings.performance.menuMotionMode === 'snappy' ? 'SNAPPY' : 'FULL'}>
              <PerformanceModeSegmented<MenuMotionPerformanceMode>
                value={settings.performance.menuMotionMode}
                options={[
                  { value: 'full', label: 'Full' },
                  { value: 'snappy', label: 'Snappy' }
                ]}
                onChange={(menuMotionMode) => updateSettings((current) => ({ ...current, performance: { ...current.performance, menuMotionMode } }))}
              />
            </SettingRow>
            <button className="secondary-button" onClick={() => {
              onAnalytics('settings_reset_clicked', { settings_tab: 'game', action: 'apply_recommended_performance' });
              updateSettings((current) => ({ ...current, performance: { ...current.performance, menuAttractMode: 'snappy', menuMotionMode: 'snappy' } }));
            }}>
              <Gauge size={16} />
              Apply Recommended
            </button>
          </SettingsSection>
          <SettingsSection index={5} title="Defaults" active={activeSectionIndex === 5}>
            <button className="secondary-button" onClick={() => {
              onAnalytics('settings_reset_clicked', { settings_tab: 'game' });
              clearMenuLagPromptDismissed();
              updateSettings((current) => ({
                ...current,
                game: cloneSettings(defaultGameSettings).game,
                training: cloneSettings(defaultGameSettings).training,
                performance: cloneSettings(defaultGameSettings).performance
              }));
            }}>
              <RotateCcw size={16} />
              Reset Game Settings
            </button>
          </SettingsSection>
        </div>
      );
    }

    if (activeTab === 'controls') {
      const keyboard = settings.controls.keyboard[activePlayer - 1];
      const gamepad = settings.controls.gamepad[activePlayer - 1];
      const keyboardCombos = settings.controls.keyboardCombos[activePlayer - 1];
      const gamepadCombos = settings.controls.gamepadCombos[activePlayer - 1];
      return (
        <div className="settings-section-stack">
          {duplicateRequest && <p className="settings-warning">{duplicateRequest.key} is already bound to {duplicateRequest.owner}. Press it again to replace that binding.</p>}
          <SettingsSection index={0} title="Keyboard Mapping" active={activeSectionIndex === 0}>
            <SettingRow label="Control Scheme" value={settings.game.controlScheme === 'beginner' ? 'BEGINNER' : 'KORE'}>
              <div className="mini-segmented">
                <button className={settings.game.controlScheme === 'kore' ? 'active' : ''} onClick={() => updateSettings((current) => ({ ...current, game: { ...current.game, controlScheme: 'kore' } }))}>KORE</button>
                <button className={settings.game.controlScheme === 'beginner' ? 'active' : ''} onClick={() => updateSettings((current) => ({ ...current, game: { ...current.game, controlScheme: 'beginner' } }))}>BEGINNER</button>
              </div>
            </SettingRow>
            <SettingRow label="Player" value={`P${activePlayer}`}>
              <div className="mini-segmented">
                <button className={activePlayer === 1 ? 'active' : ''} onClick={() => setActivePlayer(1)}>P1</button>
                <button className={activePlayer === 2 ? 'active' : ''} onClick={() => setActivePlayer(2)}>P2</button>
              </div>
            </SettingRow>
            <SettingToggle
              label="Up Hold Jumps"
              checked={settings.controls.upHoldJumps}
              onChange={(checked) => updateSettings((current) => ({ ...current, controls: { ...current.controls, upHoldJumps: checked } }))}
            />
            {controlActions.map((action) => (
              <div className="binding-row" key={action}>
                <div>
                  <strong>{formatActionLabel(action, settings.game.controlScheme)}</strong>
                  <small>{keyboard[action].map(formatKeyName).join(' / ') || 'Unbound'}</small>
                </div>
                <button className={remapRequest?.player === activePlayer && remapRequest.action === action ? 'capture' : ''} onClick={() => {
                  setActivePlayer(activePlayer);
                  setRemapRequest({ player: activePlayer, action });
                  setComboRemapRequest(null);
                  setDuplicateRequest(null);
                }}>
                  {remapRequest?.player === activePlayer && remapRequest.action === action ? 'Press key' : 'Remap'}
                </button>
              </div>
            ))}
          </SettingsSection>
          <SettingsSection index={1} title="Keyboard Combos" active={activeSectionIndex === 1}>
            {buttonComboHotkeys.map((combo) => (
              <div className="binding-row" key={combo.id}>
                <div>
                  <strong>{formatButtonComboLabel(combo.id, settings.game.controlScheme)}</strong>
                  <small>{(keyboardCombos[combo.id] ?? []).map(formatKeyName).join(' / ') || 'Unbound'}</small>
                </div>
                <button className={comboRemapRequest?.player === activePlayer && comboRemapRequest.comboId === combo.id ? 'capture' : ''} onClick={() => {
                  setActivePlayer(activePlayer);
                  setComboRemapRequest({ player: activePlayer, comboId: combo.id });
                  setRemapRequest(null);
                  setDuplicateRequest(null);
                }}>
                  {comboRemapRequest?.player === activePlayer && comboRemapRequest.comboId === combo.id ? 'Press key' : 'Remap'}
                </button>
              </div>
            ))}
          </SettingsSection>
          <SettingsSection index={2} title="Gamepad Mapping" active={activeSectionIndex === 2}>
            {controlActions.map((action) => (
              <div className="binding-row" key={action}>
                <div>
                  <strong>{formatActionLabel(action, settings.game.controlScheme)}</strong>
                  <small>{formatGamepadButtonName(gamepad[action]?.[0])}</small>
                </div>
                <div className="gamepad-stepper" aria-label={`${formatActionLabel(action, settings.game.controlScheme)} gamepad button`}>
                  <button aria-label="Previous gamepad button" onClick={() => updateSettings((current) => adjustGamepadButton(current, activePlayer, action, -1))}>
                    <ChevronLeft size={18} />
                  </button>
                  <GamepadButtonPrompt button={gamepad[action]?.[0]} />
                  <button aria-label="Next gamepad button" onClick={() => updateSettings((current) => adjustGamepadButton(current, activePlayer, action, 1))}>
                    <ChevronRight size={18} />
                  </button>
                </div>
              </div>
            ))}
          </SettingsSection>
          <SettingsSection index={3} title="Gamepad Combos" active={activeSectionIndex === 3}>
            {buttonComboHotkeys.map((combo) => (
              <div className="binding-row" key={combo.id}>
                <div>
                  <strong>{formatButtonComboLabel(combo.id, settings.game.controlScheme)}</strong>
                  <small>{formatGamepadButtonName(gamepadCombos[combo.id]?.[0])}</small>
                </div>
                <div className="gamepad-stepper" aria-label={`${formatButtonComboLabel(combo.id, settings.game.controlScheme)} gamepad button`}>
                  <button aria-label="Previous gamepad button" onClick={() => updateSettings((current) => adjustGamepadComboButton(current, activePlayer, combo.id, -1))}>
                    <ChevronLeft size={18} />
                  </button>
                  <GamepadButtonPrompt button={gamepadCombos[combo.id]?.[0]} />
                  <button aria-label="Next gamepad button" onClick={() => updateSettings((current) => adjustGamepadComboButton(current, activePlayer, combo.id, 1))}>
                    <ChevronRight size={18} />
                  </button>
                </div>
              </div>
            ))}
          </SettingsSection>
          <SettingsSection index={4} title="Input Test" active={activeSectionIndex === 4}>
            <SettingRow label="Last Input" value={inputTest}>
              <span className="setting-readout">{inputTest}</span>
            </SettingRow>
          </SettingsSection>
          <SettingsSection index={5} title="Defaults" active={activeSectionIndex === 5}>
            <button className="secondary-button" onClick={() => {
              onAnalytics('settings_reset_clicked', { settings_tab: 'controls' });
              setSettings((current) => ({ ...current, controls: cloneSettings(defaultGameSettings).controls }));
            }}>
              <RotateCcw size={16} />
              Reset Controls
            </button>
          </SettingsSection>
        </div>
      );
    }

    if (activeTab === 'camera') {
      return (
        <div className="settings-section-stack">
          <SettingsSection index={0} title="Fight Camera" active={activeSectionIndex === 0}>
            <SettingSlider label="Distance" value={settings.camera.distance} min={0.7} max={1.35} step={0.01} onChange={(value) => updateSettings((current) => ({ ...current, camera: { ...current.camera, distance: value } }))} />
            <SettingSlider label="Height" value={settings.camera.height} min={0.75} max={1.35} step={0.01} onChange={(value) => updateSettings((current) => ({ ...current, camera: { ...current.camera, height: value } }))} />
          </SettingsSection>
          <SettingsSection index={1} title="Tracking" active={activeSectionIndex === 1}>
            <SettingSlider label="Smoothing" value={settings.camera.smoothing} min={0.35} max={1.5} step={0.01} onChange={(value) => updateSettings((current) => ({ ...current, camera: { ...current.camera, smoothing: value } }))} />
          </SettingsSection>
          <SettingsSection index={2} title="Zoom" active={activeSectionIndex === 2}>
            <SettingSlider label="Zoom Bias" value={settings.camera.zoomBias} min={0.75} max={1.35} step={0.01} onChange={(value) => updateSettings((current) => ({ ...current, camera: { ...current.camera, zoomBias: value } }))} />
          </SettingsSection>
          <SettingsSection index={3} title="Defaults" active={activeSectionIndex === 3}>
            <button className="secondary-button" onClick={() => {
              onAnalytics('settings_reset_clicked', { settings_tab: 'camera' });
              updateSettings((current) => ({ ...current, camera: cloneSettings(defaultGameSettings).camera }));
            }}>
              <RotateCcw size={16} />
              Reset Camera
            </button>
          </SettingsSection>
        </div>
      );
    }

    if (activeTab === 'display') {
      return (
        <div className="settings-section-stack">
          <SettingsSection index={0} title="HUD" active={activeSectionIndex === 0}>
            <SettingSlider label="HUD Scale" value={settings.display.hudScale} min={0.78} max={1.25} step={0.01} onChange={(value) => updateSettings((current) => ({ ...current, display: { ...current.display, hudScale: value } }))} />
            <SettingToggle label="Impact Sparks" checked={settings.display.impactSparks.enabled} onChange={(checked) => updateSettings((current) => ({ ...current, display: { ...current.display, impactSparks: { ...current.display.impactSparks, enabled: checked } } }))} />
            <SettingToggle label="Cinematic Impact FX" checked={settings.display.impactSparks.cinematic} onChange={(checked) => updateSettings((current) => ({ ...current, display: { ...current.display, impactSparks: { ...current.display.impactSparks, cinematic: checked } } }))} />
            <SettingRow label="Spark Shape" value={IMPACT_SPARK_SHAPE_OPTIONS.find((option) => option.value === settings.display.impactSparks.shape)?.label ?? 'Voxel Burst'}>
              <div className="mini-segmented impact-spark-shape-picker">
                {IMPACT_SPARK_SHAPE_OPTIONS.map(({ value, label }) => (
                  <button key={value} className={settings.display.impactSparks.shape === value ? 'active' : ''} onClick={() => updateSettings((current) => ({ ...current, display: { ...current.display, impactSparks: { ...current.display.impactSparks, shape: value } } }))}>{label}</button>
                ))}
              </div>
            </SettingRow>
            <SettingRow label="Hit Spark Primary" value={settings.display.impactSparks.hitColor.toUpperCase()}>
              <input type="color" value={settings.display.impactSparks.hitColor} onChange={(event) => updateSettings((current) => ({ ...current, display: { ...current.display, impactSparks: { ...current.display.impactSparks, hitColor: event.target.value } } }))} />
            </SettingRow>
            <SettingRow label="Hit Spark Accent" value={settings.display.impactSparks.hitAccentColor.toUpperCase()}>
              <input type="color" value={settings.display.impactSparks.hitAccentColor} onChange={(event) => updateSettings((current) => ({ ...current, display: { ...current.display, impactSparks: { ...current.display.impactSparks, hitAccentColor: event.target.value } } }))} />
            </SettingRow>
            <SettingRow label="Block Spark" value={settings.display.impactSparks.blockColor.toUpperCase()}>
              <input type="color" value={settings.display.impactSparks.blockColor} onChange={(event) => updateSettings((current) => ({ ...current, display: { ...current.display, impactSparks: { ...current.display.impactSparks, blockColor: event.target.value } } }))} />
            </SettingRow>
            <SettingSlider label="Spark Size" value={settings.display.impactSparks.size} min={0.5} max={1.8} step={0.01} onChange={(value) => updateSettings((current) => ({ ...current, display: { ...current.display, impactSparks: { ...current.display.impactSparks, size: value } } }))} />
            <SettingSlider label="Spark Intensity" value={settings.display.impactSparks.intensity} min={0.35} max={2} step={0.01} onChange={(value) => updateSettings((current) => ({ ...current, display: { ...current.display, impactSparks: { ...current.display.impactSparks, intensity: value } } }))} />
          </SettingsSection>
          <SettingsSection index={1} title="Touch Controls" active={activeSectionIndex === 1}>
            <SettingRow label="Touch Controls" value={settings.display.touchControls.toUpperCase()}>
              <div className="mini-segmented">
                {(['auto', 'on', 'off'] as const).map((value) => (
                  <button key={value} className={settings.display.touchControls === value ? 'active' : ''} onClick={() => updateSettings((current) => ({ ...current, display: { ...current.display, touchControls: value } }))}>{value}</button>
                ))}
              </div>
            </SettingRow>
          </SettingsSection>
          <SettingsSection index={2} title="Cursor" active={activeSectionIndex === 2}>
            <CursorPicker
              selectedCursor={selectedCursor}
              visibleOptions={visibleCursorOptions}
              styleFilter={cursorStyleFilter}
              onStyleFilterChange={setCursorStyleFilter}
              onScaleFilterChange={selectCursorScale}
              onChange={(cursorId) => updateSettings((current) => ({ ...current, display: { ...current.display, cursorId } }))}
            />
          </SettingsSection>
          <SettingsSection index={3} title="Motion" active={activeSectionIndex === 3}>
            <SettingToggle label="Reduced Motion" checked={settings.display.reducedMotion} onChange={(checked) => updateSettings((current) => ({ ...current, display: { ...current.display, reducedMotion: checked } }))} />
            <SettingRow label="Movement Smoke" value={MOVEMENT_SMOKE_STYLE_OPTIONS.find((option) => option.value === settings.display.movementSmokeStyle)?.label ?? 'Speed Trail'}>
              <div className="mini-segmented movement-smoke-style-picker">
                {MOVEMENT_SMOKE_STYLE_OPTIONS.map(({ value, label }) => (
                  <button key={value} className={settings.display.movementSmokeStyle === value ? 'active' : ''} onClick={() => updateSettings((current) => ({ ...current, display: { ...current.display, movementSmokeStyle: value } }))}>{label}</button>
                ))}
              </div>
            </SettingRow>
          </SettingsSection>
          <SettingsSection index={4} title="Debug" active={activeSectionIndex === 4}>
            <SettingToggle label="Debug Overlay" checked={settings.display.debugOverlay} onChange={(checked) => updateSettings((current) => ({ ...current, display: { ...current.display, debugOverlay: checked } }))} />
          </SettingsSection>
        </div>
      );
    }

    if (activeTab === 'console') {
      return <OptionsConsole onMemoryCardLoaded={onMemoryCardLoaded} activeSectionIndex={activeSectionIndex} onOpenStarterGuide={onOpenStarterGuide} onAnalytics={onAnalytics} />;
    }

    return (
      <div className="settings-section-stack">
        <SettingsSection index={0} title="Menu Music" active={activeSectionIndex === 0}>
          <SettingToggle
            label="Main Menu Music"
            checked={settings.audio.menuMusic}
            onChange={(checked) => updateSettings((current) => ({ ...current, audio: { ...current.audio, menuMusic: checked } }))}
          />
          <SettingRow label="BGM Source" value={`${menuBgmTrackCount} local tracks`}>
            <span className="setting-readout">Repo MP3 Library</span>
          </SettingRow>
          <SettingRow label="Menu Song" value={menuBgmTrackTitle}>
            <div className="audio-track-controls" role="group" aria-label="Current BGM song">
              <button type="button" onClick={() => onMenuBgmTrackChange(settings.audio.bgmTrackIndex - 1)}>
                <ChevronLeft size={18} />
                Previous
              </button>
              <button type="button" onClick={() => onMenuBgmTrackChange(settings.audio.bgmTrackIndex + 1)}>
                Next
                <ChevronRight size={18} />
              </button>
            </div>
          </SettingRow>
        </SettingsSection>
        <SettingsSection index={1} title="Stage Music" active={activeSectionIndex === 1}>
          <SettingRow label="Selected Stage" value={selectedStageName}>
            <span className="setting-readout">{selectedStageBgmTitle}</span>
          </SettingRow>
          <SettingRow label="Fight Playback" value="Enabled">
            <span className="setting-readout">Uses stage BGM</span>
          </SettingRow>
        </SettingsSection>
        <SettingsSection index={2} title="Mix" active={activeSectionIndex === 2}>
          <SettingSlider label="Master" value={settings.audio.master} min={0} max={1} step={0.01} onChange={(value) => updateSettings((current) => ({ ...current, audio: { ...current.audio, master: value } }))} />
          <SettingSlider label="Music" value={settings.audio.music} min={0} max={1} step={0.01} onChange={(value) => updateSettings((current) => ({ ...current, audio: { ...current.audio, music: value } }))} />
          <SettingSlider label="Ambience" value={settings.audio.ambience} min={0} max={1} step={0.01} onChange={(value) => updateSettings((current) => ({ ...current, audio: { ...current.audio, ambience: value } }))} />
          <SettingSlider label="SFX" value={settings.audio.sfx} min={0} max={1} step={0.01} onChange={(value) => updateSettings((current) => ({ ...current, audio: { ...current.audio, sfx: value } }))} />
          <SettingSlider label="Voices" value={settings.audio.voices} min={0} max={1} step={0.01} onChange={(value) => updateSettings((current) => ({ ...current, audio: { ...current.audio, voices: value } }))} />
          <SettingSlider label="Hit Effects" value={settings.audio.hitSfx} min={0} max={2} step={0.01} onChange={(value) => updateSettings((current) => ({ ...current, audio: { ...current.audio, hitSfx: value } }))} />
          <SettingToggle label="Mute All" checked={settings.audio.muted} onChange={(checked) => updateSettings((current) => ({ ...current, audio: { ...current.audio, muted: checked } }))} />
        </SettingsSection>
      </div>
    );
  };

  return (
    <div className="settings-screen">
      <header className="options-header">
        <nav className="options-tabs" aria-label="Options tabs">
          <span data-testid="options-tab-previous-hint">{tabPrompts.previous}</span>
          {settingsTabs.map((tab) => (
            <button key={tab} className={activeTab === tab ? 'active' : ''} onClick={() => {
              setActiveTab(tab);
              onAnalytics('navigation_clicked', { source: 'settings_tab', destination: tab });
            }}>
              {tabLabels[tab]}
            </button>
          ))}
          <span data-testid="options-tab-next-hint">{tabPrompts.next}</span>
        </nav>
      </header>
      <section className="options-layout">
        <aside className="options-sidebar">
          {sidebars[activeTab].map((item, index) => (
            <button key={item} className={activeSectionIndex === index ? 'active' : ''} onClick={() => selectSidebarSection(index)}>{item}</button>
          ))}
        </aside>
        <section ref={editorRef} className="options-editor" aria-label={`${tabLabels[activeTab]} settings`}>
          {renderEditor()}
        </section>
      </section>
      <footer className="settings-support-footer" aria-label="Community links">
        <button className="secondary-button" onClick={() => {
          onAnalytics('navigation_clicked', { destination: 'menu', source: 'settings_back' });
          onBack();
        }}>
          <Home size={18} />
          Back
        </button>
        <div className="support-actions">
          <a className="support-button discord-button" href="https://discord.gg/yDcrFsmTx7" target="_blank" rel="noreferrer" onClick={() => onAnalytics('external_link_clicked', { destination: 'discord', source: 'settings' })}>
            <span className="discord-mark" aria-hidden="true">Discord</span>
            <span>Join the Discord</span>
          </a>
          <a className="support-button patreon-button" href="https://www.patreon.com/cw/playKORE" target="_blank" rel="noreferrer" onClick={() => onAnalytics('external_link_clicked', { destination: 'patreon', source: 'settings' })}>
            <span className="patreon-mark" aria-hidden="true">p</span>
            <span>Become a patron</span>
          </a>
        </div>
      </footer>
    </div>
  );
}

function SettingRow({ label, value, children }: { label: string; value: string; children: ReactNode }) {
  return (
    <article className="setting-row">
      <div>
        <strong>{label}</strong>
        <small>{value}</small>
      </div>
      <div>{children}</div>
    </article>
  );
}

type ConsoleLine = {
  id: number;
  kind: 'system' | 'command' | 'success' | 'error';
  text: string;
};

type InstallerPlatformId = 'windows' | 'mac' | 'steamdeck' | 'linux';
type InstallerAssetType = 'installer' | 'flatpak' | 'appimage' | 'script' | 'steam-art';
type InstallerAsset = {
  type?: InstallerAssetType;
  primary?: boolean;
  label?: string;
  filename: string;
  url: string;
  size?: number;
  sha256?: string;
};
type InstallerEntry = InstallerAsset & {
  id: InstallerPlatformId;
  label: string;
  version: string;
  recommended?: boolean;
  notes?: string;
  installCommand?: string;
  assets?: InstallerAsset[];
};

let consoleLineId = 0;

function OptionsConsole({
  onMemoryCardLoaded,
  activeSectionIndex,
  onOpenStarterGuide,
  onAnalytics
}: {
  onMemoryCardLoaded: () => void;
  activeSectionIndex: number;
  onOpenStarterGuide: () => void;
  onAnalytics: AnalyticsCapture;
}) {
  const [command, setCommand] = useState('');
  const [lines, setLines] = useState<ConsoleLine[]>(() => [
    { id: ++consoleLineId, kind: 'system', text: 'KORE local console online.' },
    { id: ++consoleLineId, kind: 'system', text: 'Type /help for commands. Starter access is limited to memory-card save export and import.' }
  ]);
  const [installers, setInstallers] = useState<InstallerEntry[] | null>(null);
  const [installerManifestFailed, setInstallerManifestFailed] = useState(false);
  const fileInputRef = useRef<HTMLInputElement | null>(null);

  const appendLine = useCallback((kind: ConsoleLine['kind'], text: string) => {
    setLines((current) => [...current.slice(-26), { id: ++consoleLineId, kind, text }]);
  }, []);

  const importCardText = useCallback((source: string) => {
    const payload = importMemoryCard(source);
    onMemoryCardLoaded();
    appendLine('success', `Loaded memory card from KORE ${payload.appVersion}. ${formatMemoryCardSummary(payload)}`);
    onAnalytics('memory_card_action', { action: 'import', status: 'success' });
  }, [appendLine, onAnalytics, onMemoryCardLoaded]);

  const copyMemoryCard = useCallback(async () => {
    const serialized = serializeMemoryCard();
    if (!navigator.clipboard?.writeText) {
      appendLine('error', 'Clipboard is unavailable. Use /memorycard export to download a card file.');
      onAnalytics('memory_card_action', { action: 'copy', status: 'error', reason: 'clipboard_unavailable' });
      return;
    }
    await navigator.clipboard.writeText(serialized);
    appendLine('success', `Copied memory card to clipboard. ${formatMemoryCardSummary(createMemoryCardPayload())}`);
    onAnalytics('memory_card_action', { action: 'copy', status: 'success' });
  }, [appendLine, onAnalytics]);

  const exportMemoryCard = useCallback(() => {
    const payload = createMemoryCardPayload();
    downloadMemoryCard();
    appendLine('success', `Exported memory card file. ${formatMemoryCardSummary(payload)}`);
    onAnalytics('memory_card_action', { action: 'export', status: 'success' });
  }, [appendLine, onAnalytics]);

  const runCommand = useCallback(async (rawCommand: string) => {
    const trimmed = rawCommand.trim();
    if (!trimmed) return;
    appendLine('command', `> ${trimmed}`);
    const [head, subcommand, ...rest] = trimmed.split(/\s+/);
    try {
      if (head === '/help') {
        appendLine('system', '/memorycard - show save-card status.');
        appendLine('system', '/memorycard export - download your save card.');
        appendLine('system', '/memorycard copy - copy your save card JSON.');
        appendLine('system', '/memorycard load <card-json> - import pasted card JSON.');
        appendLine('system', 'More local mod, cheat, and sprite commands will unlock here later.');
        return;
      }
      if (head === '/memorycard') {
        if (!subcommand) {
          appendLine('system', `Current card status: ${formatMemoryCardSummary(createMemoryCardPayload())}`);
          appendLine('system', 'Use /memorycard export, /memorycard copy, or the Load Card button.');
          return;
        }
        if (subcommand === 'export') {
          exportMemoryCard();
          return;
        }
        if (subcommand === 'copy') {
          await copyMemoryCard();
          return;
        }
        if (subcommand === 'load') {
          const pastedCard = rest.join(' ');
          if (!pastedCard) {
            appendLine('error', 'Paste memory-card JSON after /memorycard load, or use the Load Card button.');
            return;
          }
          importCardText(pastedCard);
          return;
        }
      }
      appendLine('error', `Unknown command: ${head}. Type /help.`);
      onAnalytics('memory_card_action', { action: 'console_command', status: 'unknown' });
    } catch (error) {
      appendLine('error', error instanceof Error ? error.message : 'Console command failed.');
      onAnalytics('memory_card_action', { action: 'console_command', status: 'error' });
    }
  }, [appendLine, copyMemoryCard, exportMemoryCard, importCardText, onAnalytics]);

  const handleFile = async (file?: File | null) => {
    if (!file) return;
    try {
      importCardText(await file.text());
      if (fileInputRef.current) fileInputRef.current.value = '';
    } catch (error) {
      appendLine('error', error instanceof Error ? error.message : 'Memory card import failed.');
      onAnalytics('memory_card_action', { action: 'import', status: 'error' });
    }
  };

  useEffect(() => {
    let cancelled = false;
    setInstallerManifestFailed(false);
    fetch('/installers/manifest.json', { cache: 'no-store' })
      .then((response) => {
        if (!response.ok) throw new Error(`Installer manifest returned ${response.status}`);
        return response.json();
      })
      .then((payload) => {
        if (!cancelled) setInstallers(normalizeInstallerManifest(payload));
      })
      .catch(() => {
        if (!cancelled) {
          setInstallers([]);
          setInstallerManifestFailed(true);
        }
      });
    return () => {
      cancelled = true;
    };
  }, []);

  return (
    <div className={`settings-section-stack options-console-stack${activeSectionIndex === 2 ? ' options-console-stack-installers' : ''}`}>
      <SettingsSection index={0} title="Terminal" active={activeSectionIndex === 0} showTitle={false}>
        <section className="options-console" aria-label="KORE console terminal">
          <div className="options-console-topline">
            <span><Terminal size={16} /> LOCAL SHELL</span>
            <strong>READY</strong>
          </div>
          <div className="options-console-output" aria-live="polite">
            {lines.map((line) => (
              <p key={line.id} className={`console-line console-line-${line.kind}`}>{line.text}</p>
            ))}
          </div>
          <form
            className="options-console-input"
            onSubmit={(event) => {
              event.preventDefault();
              void runCommand(command);
              setCommand('');
            }}
          >
            <span aria-hidden="true">$</span>
            <input
              value={command}
              onChange={(event) => setCommand(event.target.value)}
              placeholder="Type /help for commands"
              spellCheck={false}
              autoComplete="off"
            />
            <button type="submit">Run</button>
          </form>
        </section>
      </SettingsSection>
      <SettingsSection index={1} title="Memory Card" active={activeSectionIndex === 1} showTitle={false}>
        <article className="memory-card-panel">
          <div>
            <strong>Portable Save Card</strong>
            <small>{formatMemoryCardSummary(createMemoryCardPayload())}</small>
          </div>
          <div className="memory-card-actions">
            <button type="button" className="memory-card-button memory-card-button-save" onClick={exportMemoryCard}>
              <img src="/ui/memory-card-button.png" alt="" aria-hidden="true" />
              <span>Save Data</span>
            </button>
            <button type="button" className="memory-card-button memory-card-button-copy" onClick={() => void copyMemoryCard()}>
              <img src="/ui/memory-card-button.png" alt="" aria-hidden="true" />
              <span>Copy Data</span>
            </button>
            <button type="button" className="memory-card-button memory-card-button-load" onClick={() => fileInputRef.current?.click()}>
              <img src="/ui/memory-card-button.png" alt="" aria-hidden="true" />
              <span>Load Data</span>
            </button>
          </div>
          <input
            ref={fileInputRef}
            className="memory-card-file-input"
            type="file"
            accept=".json,.korecard,application/json"
            onChange={(event) => void handleFile(event.target.files?.[0])}
          />
          <dl className="memory-card-command-list">
            <div><dt>/help</dt><dd>Show commands</dd></div>
            <div><dt>/memorycard export</dt><dd>Download save card</dd></div>
            <div><dt>/memorycard copy</dt><dd>Copy card JSON</dd></div>
            <div><dt>/memorycard load</dt><dd>Import pasted JSON</dd></div>
          </dl>
        </article>
      </SettingsSection>
      <SettingsSection index={2} title="Installers" active={activeSectionIndex === 2} showTitle={false} className="settings-section-installers">
        <OptionsInstallersPanel installers={installers} manifestFailed={installerManifestFailed} />
      </SettingsSection>
      <SettingsSection index={3} title="Debug" active={activeSectionIndex === 3} showTitle={false}>
        <OptionsDebugPanel />
      </SettingsSection>
      <SettingsSection index={4} title="About" active={activeSectionIndex === 4} showTitle={false}>
        <article className="about-kore-panel" aria-label="About game">
          <div className="about-kore-heading">
            <img src="/brand/kore-logo-generated.png" alt="Game logo" />
            <strong>Developed by BG Games.</strong>
          </div>
          <p className="about-kore-copy">
            Disclaimer: Game assets owned by their respective businesses, no copyright infringements intended.
            This is a fan-based project intended for educational purposes only. This engine is a free-to-play
            open-source 3D fighting game engine built in the browser. It can run on mobile, iPad, Xbox, PS5,
            PC, you name it. Full online support and arcade mode. Will you become a KORE fighter?
          </p>
          <button type="button" className="secondary-button about-kore-guide-button" onClick={onOpenStarterGuide}>
            <BookOpen size={18} />
            Open Starter Guide
          </button>
        </article>
      </SettingsSection>
    </div>
  );
}

function OptionsDebugPanel() {
  const checks = useMemo(() => getGameplaySupportChecks(), []);
  const allPassed = checks.length > 0 && checks.every((check) => check.passed);
  return (
    <article className="debug-panel" aria-label="Device debug checks">
      <div className="debug-panel-heading">
        <span><Terminal size={18} /> DEBUG</span>
        <strong>{allPassed ? 'SUPPORTED' : 'REVIEW'}</strong>
      </div>
      <p>
        {allPassed
          ? 'This browser and device passed the gameplay support checks.'
          : 'One or more support checks may affect gameplay on this browser or device.'}
      </p>
      <div className="debug-check-list">
        {checks.map((check) => (
          <DebugCheckRow key={check.id} check={check} />
        ))}
      </div>
    </article>
  );
}

function DebugCheckRow({ check }: { check: SupportCheck }) {
  return (
    <div className={`debug-check-row ${check.passed ? 'is-passed' : 'is-failed'}`}>
      <span className="debug-check-icon" aria-hidden="true">
        {check.passed ? <CheckCircle2 size={21} /> : <XCircle size={21} />}
      </span>
      <div>
        <strong>{check.label}</strong>
        <small>{check.detail}</small>
      </div>
      <em>{check.passed ? 'Pass' : check.level === 'unsupported' ? 'Unsupported' : 'Warning'}</em>
    </div>
  );
}

function normalizeInstallerManifest(payload: unknown): InstallerEntry[] {
  if (!payload || typeof payload !== 'object') return [];
  const installers = (payload as { installers?: unknown }).installers;
  if (!Array.isArray(installers)) return [];
  return installers
    .map((item) => {
      if (!item || typeof item !== 'object') return null;
      const record = item as Record<string, unknown>;
      const id = record.id;
      const label = record.label;
      const filename = record.filename;
      const url = record.url;
      const version = record.version;
      if (!isInstallerPlatformId(id) || typeof label !== 'string' || typeof filename !== 'string' || typeof url !== 'string' || typeof version !== 'string') {
        return null;
      }
      const entry: InstallerEntry = {
        id,
        label,
        filename,
        url,
        version,
        size: typeof record.size === 'number' ? record.size : undefined,
        sha256: typeof record.sha256 === 'string' ? record.sha256 : undefined,
        recommended: record.recommended === true,
        notes: typeof record.notes === 'string' ? record.notes : undefined,
        type: isInstallerAssetType(record.type) ? record.type : undefined,
        primary: record.primary === true,
        installCommand: typeof record.installCommand === 'string' ? record.installCommand : undefined,
        assets: Array.isArray(record.assets)
          ? record.assets
              .map((asset) => normalizeInstallerAsset(asset))
              .filter((asset): asset is InstallerAsset => Boolean(asset))
          : undefined
      };
      return entry;
    })
    .filter((entry): entry is InstallerEntry => Boolean(entry));
}

function normalizeInstallerAsset(asset: unknown): InstallerAsset | null {
  if (!asset || typeof asset !== 'object') return null;
  const record = asset as Record<string, unknown>;
  if (typeof record.filename !== 'string' || typeof record.url !== 'string') return null;
  return {
    type: isInstallerAssetType(record.type) ? record.type : undefined,
    primary: record.primary === true,
    label: typeof record.label === 'string' ? record.label : undefined,
    filename: record.filename,
    url: record.url,
    size: typeof record.size === 'number' ? record.size : undefined,
    sha256: typeof record.sha256 === 'string' ? record.sha256 : undefined
  };
}

function isInstallerAssetType(value: unknown): value is InstallerAssetType {
  return value === 'installer' || value === 'flatpak' || value === 'appimage' || value === 'script' || value === 'steam-art';
}

function isInstallerPlatformId(value: unknown): value is InstallerPlatformId {
  return value === 'windows' || value === 'mac' || value === 'steamdeck' || value === 'linux';
}

function detectInstallerPlatform(): InstallerPlatformId {
  if (typeof navigator === 'undefined') return 'windows';
  const nav = navigator as Navigator & { userAgentData?: { platform?: string } };
  const platform = `${nav.userAgentData?.platform ?? ''} ${navigator.platform ?? ''} ${navigator.userAgent ?? ''}`;
  if (/mac/i.test(platform)) return 'mac';
  if (/win/i.test(platform)) return 'windows';
  if (/steamos|steam deck|jupiter|galileo/i.test(platform)) return 'steamdeck';
  if (/linux/i.test(platform)) {
    const isDeckSized = typeof window !== 'undefined' && Math.min(window.screen.width, window.screen.height) <= 800 && Math.max(window.screen.width, window.screen.height) <= 1400;
    return isDeckSized && navigator.maxTouchPoints > 0 ? 'steamdeck' : 'linux';
  }
  return 'windows';
}

function formatInstallerSize(size?: number) {
  if (!size || !Number.isFinite(size) || size <= 0) return 'Size pending';
  const units = ['B', 'KB', 'MB', 'GB'];
  let value = size;
  let unitIndex = 0;
  while (value >= 1024 && unitIndex < units.length - 1) {
    value /= 1024;
    unitIndex += 1;
  }
  return `${value >= 10 || unitIndex === 0 ? value.toFixed(0) : value.toFixed(1)} ${units[unitIndex]}`;
}

function installerIcon(id: InstallerPlatformId) {
  if (id === 'mac') return <Apple size={20} />;
  if (id === 'steamdeck') return <Gamepad2 size={20} />;
  if (id === 'linux') return <Package size={20} />;
  return <Laptop size={20} />;
}

function installerAssetIcon(type?: InstallerAssetType) {
  if (type === 'script') return <Terminal size={15} />;
  if (type === 'flatpak' || type === 'appimage') return <Package size={15} />;
  return <Download size={15} />;
}

function OptionsInstallersPanel({
  installers,
  manifestFailed
}: {
  installers: InstallerEntry[] | null;
  manifestFailed: boolean;
}) {
  const detectedPlatform = useMemo(() => detectInstallerPlatform(), []);
  const hasInstallers = Boolean(installers?.length);
  const [copiedCommandKey, setCopiedCommandKey] = useState<string | null>(null);

  const copyInstallCommand = useCallback(async (key: string, command: string) => {
    if (!navigator.clipboard?.writeText) return;
    await navigator.clipboard.writeText(command);
    setCopiedCommandKey(key);
    window.setTimeout(() => setCopiedCommandKey((current) => current === key ? null : current), 1600);
  }, []);

  if (installers === null) {
    return (
      <article className="installer-panel" aria-label="Desktop installers">
        <div className="installer-panel-heading">
          <span><Download size={18} /> INSTALLERS</span>
          <strong>LOADING</strong>
        </div>
        <div className="installer-empty-state">
          <Package size={34} />
          <strong>Checking installer manifest</strong>
          <p>KORE is looking for the latest desktop builds.</p>
        </div>
      </article>
    );
  }

  if (!hasInstallers) {
    return (
      <article className="installer-panel" aria-label="Desktop installers">
        <div className="installer-panel-heading">
          <span><Download size={18} /> INSTALLERS</span>
          <strong>{manifestFailed ? 'OFFLINE' : 'PENDING'}</strong>
        </div>
        <div className="installer-empty-state">
          <Package size={34} />
          <strong>Installers are being prepared</strong>
          <p>Windows, Mac, Steam Deck, and Linux builds will appear here once the release files are published.</p>
        </div>
      </article>
    );
  }

  return (
    <article className="installer-panel" aria-label="Desktop installers">
      <div className="installer-panel-heading">
        <span><Download size={18} /> INSTALLERS</span>
        <strong>{detectedPlatform.toUpperCase()}</strong>
      </div>
      <div className="installer-grid">
        {installers.map((installer) => {
          const recommended = installer.recommended || installer.id === detectedPlatform;
          const assets = installer.assets?.length ? installer.assets : [installer];
          const sortedAssets = [...assets].sort((left, right) => Number(Boolean(right.primary)) - Number(Boolean(left.primary)));
          const primaryAsset = sortedAssets.find((asset) => asset.primary) ?? sortedAssets[0];
          const isSteamDeckFlatpak = installer.id === 'steamdeck' && primaryAsset?.type === 'flatpak';
          const commandKey = `${installer.id}-install-command`;
          return (
            <section key={installer.id} className={`installer-card ${installer.id === 'steamdeck' ? 'installer-card-steamdeck' : ''} ${recommended ? 'installer-card-recommended' : ''}`}>
              <div className="installer-card-title">
                <span>{installerIcon(installer.id)}</span>
                <div>
                  <strong>{installer.label}</strong>
                  <small>{recommended ? 'Recommended for this device' : `KORE ${installer.version}`}</small>
                </div>
              </div>
              {installer.notes && <p>{installer.notes}</p>}
              <dl>
                <div><dt>Version</dt><dd>{installer.version}</dd></div>
                <div><dt>Size</dt><dd>{formatInstallerSize(installer.size)}</dd></div>
                <div><dt>SHA</dt><dd>{installer.sha256 ? installer.sha256.slice(0, 12) : 'Pending'}</dd></div>
              </dl>
              {isSteamDeckFlatpak && (
                <div className="installer-deck-help" aria-label="Steam Deck install steps">
                  <strong>Steam Deck install</strong>
                  <ol>
                    <li>Download KORE-SteamDeck.flatpak.</li>
                    <li>Open it with Discover.</li>
                    <li>Install and launch KORE from the app launcher.</li>
                  </ol>
                  <p>If Steam does not show the art, download the cover or square logo and set it manually in your library.</p>
                </div>
              )}
              <div className="installer-actions">
                {sortedAssets.map((asset) => (
                  <a key={asset.url} className={asset.primary ? 'installer-action-primary' : 'installer-action-secondary'} href={asset.url} download onClick={() => undefined}>
                    {installerAssetIcon(asset.type)}
                    <span>{asset.label ?? asset.filename}</span>
                  </a>
                ))}
              </div>
              {installer.id === 'steamdeck' && installer.installCommand && (
                <div className="installer-command">
                  <span>Konsole fallback</span>
                  <code>{installer.installCommand}</code>
                  <button type="button" onClick={() => void copyInstallCommand(commandKey, installer.installCommand!)}>
                    <Copy size={14} />
                    {copiedCommandKey === commandKey ? 'Copied' : 'Copy'}
                  </button>
                </div>
              )}
            </section>
          );
        })}
      </div>
    </article>
  );
}

function formatMemoryCardSummary(payload: MemoryCardPayload) {
  const present = MEMORY_CARD_SAVE_KEYS.filter(({ key }) => typeof payload.slots[key] === 'string');
  if (present.length === 0) return '0 save slots captured';
  return `${present.length}/${MEMORY_CARD_SAVE_KEYS.length} save slots captured: ${present.map(({ label }) => label).join(', ')}`;
}

function CursorPicker({
  selectedCursor,
  visibleOptions,
  styleFilter,
  onStyleFilterChange,
  onScaleFilterChange,
  onChange
}: {
  selectedCursor: KoreCursorOption;
  visibleOptions: KoreCursorOption[];
  styleFilter: KoreCursorStyle;
  onStyleFilterChange: (style: KoreCursorStyle) => void;
  onScaleFilterChange: (scale: KoreCursorScale) => void;
  onChange: (cursorId: string) => void;
}) {
  return (
    <article className="cursor-setting-panel">
      <div className="cursor-setting-current">
        <div>
          <strong>Default Cursor</strong>
          <small>{selectedCursor.label} / {selectedCursor.style} {cursorScaleLabels[selectedCursor.scale]} / {selectedCursor.width}px</small>
        </div>
        <div className="cursor-preview-tile" aria-hidden="true">
          <img src={selectedCursor.url} alt="" />
        </div>
      </div>
      <div className="cursor-picker-controls">
        <div className="cursor-picker-control-group">
          <span>Style</span>
          <div className="mini-segmented">
            {(['Basic', 'Outline'] as const).map((style) => (
              <button key={style} type="button" className={styleFilter === style ? 'active' : ''} onClick={() => onStyleFilterChange(style)}>
                {style}
              </button>
            ))}
          </div>
        </div>
        <div className="cursor-picker-control-group">
          <span>Size</span>
          <div className="mini-segmented">
            {(['Default', 'Double'] as const).map((scale) => (
              <button key={scale} type="button" className={selectedCursor.scale === scale ? 'active' : ''} onClick={() => onScaleFilterChange(scale)}>
                {cursorScaleLabels[scale]}
              </button>
            ))}
          </div>
        </div>
      </div>
      <div className="cursor-picker-grid" role="listbox" aria-label="Default cursor">
        {visibleOptions.map((cursor) => (
          <button
            key={cursor.id}
            type="button"
            className={selectedCursor.id === cursor.id ? 'active' : ''}
            title={`${cursor.label} / ${cursor.style} ${cursor.scale}`}
            aria-selected={selectedCursor.id === cursor.id}
            onClick={() => onChange(cursor.id)}
          >
            <img src={cursor.url} alt="" aria-hidden="true" />
            <span>{cursor.label}</span>
          </button>
        ))}
      </div>
    </article>
  );
}

function PerformanceModeSegmented<T extends string>({
  value,
  options,
  onChange
}: {
  value: T;
  options: Array<{ value: T; label: string }>;
  onChange: (value: T) => void;
}) {
  return (
    <div className="mini-segmented">
      {options.map((option) => (
        <button key={option.value} className={value === option.value ? 'active' : ''} onClick={() => onChange(option.value)}>
          {option.label}
        </button>
      ))}
    </div>
  );
}

function SettingsSection({
  index,
  title,
  active = true,
  showTitle = true,
  className,
  children
}: {
  index: number;
  title: string;
  active?: boolean;
  showTitle?: boolean;
  className?: string;
  children: ReactNode;
}) {
  if (!active) return null;
  return (
    <section className={`settings-section${className ? ` ${className}` : ''}`} data-section-index={index}>
      {showTitle && <h3>{title}</h3>}
      <div className="settings-list">{children}</div>
    </section>
  );
}

function SettingSlider({
  label,
  value,
  min,
  max,
  step,
  onChange
}: {
  label: string;
  value: number;
  min: number;
  max: number;
  step: number;
  onChange: (value: number) => void;
}) {
  return (
    <SettingRow label={label} value={`${Math.round(value * 100)}%`}>
      <input type="range" min={min} max={max} step={step} value={value} onChange={(event) => onChange(Number(event.target.value))} />
    </SettingRow>
  );
}

function SettingToggle({ label, checked, onChange }: { label: string; checked: boolean; onChange: (checked: boolean) => void }) {
  return (
    <article className="setting-row">
      <div>
        <strong>{label}</strong>
        <small>{checked ? 'On' : 'Off'}</small>
      </div>
      <button className={`toggle-switch ${checked ? 'is-on' : ''}`} onClick={() => onChange(!checked)} aria-label={label} aria-pressed={checked}>
        <span />
      </button>
    </article>
  );
}

const gamepadButtonPrompts: Record<number, { label: string; shape: 'south' | 'east' | 'west' | 'north' | 'shoulder' | 'trigger' | 'system' | 'stick' | 'dpad'; caption: string }> = {
  0: { label: 'S', shape: 'south', caption: 'Face Down' },
  1: { label: 'E', shape: 'east', caption: 'Face Right' },
  2: { label: 'W', shape: 'west', caption: 'Face Left' },
  3: { label: 'N', shape: 'north', caption: 'Face Up' },
  4: { label: 'L1', shape: 'shoulder', caption: 'Left Shoulder' },
  5: { label: 'R1', shape: 'shoulder', caption: 'Right Shoulder' },
  6: { label: 'L2', shape: 'trigger', caption: 'Left Trigger' },
  7: { label: 'R2', shape: 'trigger', caption: 'Right Trigger' },
  8: { label: 'SEL', shape: 'system', caption: 'Select' },
  9: { label: 'STA', shape: 'system', caption: 'Start' },
  10: { label: 'L3', shape: 'stick', caption: 'Left Stick Press' },
  11: { label: 'R3', shape: 'stick', caption: 'Right Stick Press' },
  12: { label: '↑', shape: 'dpad', caption: 'D-Pad Up' },
  13: { label: '↓', shape: 'dpad', caption: 'D-Pad Down' },
  14: { label: '←', shape: 'dpad', caption: 'D-Pad Left' },
  15: { label: '→', shape: 'dpad', caption: 'D-Pad Right' },
  16: { label: '⌂', shape: 'system', caption: 'Home' }
};
const menuReservedGamepadButtons = new Set<number>();
const minConfigurableGamepadButton = 0;
const maxConfigurableGamepadButton = 16;

function GamepadButtonPrompt({ button }: { button?: number }) {
  if (button === undefined || button === null) {
    return (
      <span className="gamepad-prompt gamepad-prompt-empty" aria-label="Unbound gamepad button">
        -
      </span>
    );
  }
  const prompt = gamepadButtonPrompts[button] ?? { label: `${button}`, shape: 'system' as const, caption: `Button ${button}` };
  return (
    <span className={`gamepad-prompt gamepad-prompt-${prompt.shape}`} aria-label={prompt.caption} title={prompt.caption}>
      <span>{prompt.label}</span>
    </span>
  );
}

type KeyboardBindingTarget = { player: 1 | 2; action: ActionName } | { player: 1 | 2; comboId: ButtonComboId };

function findDuplicateKeyboardBinding(settings: GameSettings, key: string, target: KeyboardBindingTarget) {
  for (let player = 1; player <= 2; player += 1) {
    const keyboard = settings.controls.keyboard[player - 1];
    for (const action of Object.keys(keyboard) as ActionName[]) {
      if (!('comboId' in target) && player === target.player && action === target.action) continue;
      if (keyboard[action].includes(key)) return { owner: `P${player} ${formatActionLabel(action, settings.game.controlScheme)}` };
    }
    const keyboardCombos = settings.controls.keyboardCombos[player - 1];
    for (const comboId of Object.keys(keyboardCombos) as ButtonComboId[]) {
      if ('comboId' in target && player === target.player && comboId === target.comboId) continue;
      if (keyboardCombos[comboId]?.includes(key)) return { owner: `P${player} ${formatButtonComboLabel(comboId, settings.game.controlScheme)}` };
    }
  }
  return null;
}

function setKeyboardBinding(settings: GameSettings, player: 1 | 2, action: ActionName, key: string): GameSettings {
  const next = cloneSettings(settings);
  next.controls.keyboard.forEach((keyboard) => {
    for (const candidate of Object.keys(keyboard) as ActionName[]) {
      keyboard[candidate] = keyboard[candidate].filter((value) => value !== key);
    }
  });
  next.controls.keyboardCombos.forEach((keyboardCombos) => {
    for (const comboId of Object.keys(keyboardCombos) as ButtonComboId[]) {
      keyboardCombos[comboId] = keyboardCombos[comboId]?.filter((value) => value !== key);
    }
  });
  const bindings = next.controls.keyboard[player - 1][action];
  next.controls.keyboard[player - 1][action] = [key, ...bindings.filter((value) => value !== key)].slice(0, 3);
  return next;
}

function setKeyboardComboBinding(settings: GameSettings, player: 1 | 2, comboId: ButtonComboId, key: string): GameSettings {
  const next = cloneSettings(settings);
  next.controls.keyboard.forEach((keyboard) => {
    for (const action of Object.keys(keyboard) as ActionName[]) {
      keyboard[action] = keyboard[action].filter((value) => value !== key);
    }
  });
  next.controls.keyboardCombos.forEach((keyboardCombos) => {
    for (const candidate of Object.keys(keyboardCombos) as ButtonComboId[]) {
      keyboardCombos[candidate] = keyboardCombos[candidate]?.filter((value) => value !== key);
    }
  });
  const bindings = next.controls.keyboardCombos[player - 1][comboId] ?? [];
  next.controls.keyboardCombos[player - 1][comboId] = [key, ...bindings.filter((value) => value !== key)].slice(0, 3);
  return next;
}

function adjustGamepadButton(settings: GameSettings, player: 1 | 2, action: ActionName, delta: number): GameSettings {
  const next = cloneSettings(settings);
  const current = next.controls.gamepad[player - 1][action]?.[0];
  const nextButton = nextMenuConfigurableGamepadButton(current, delta);
  if (nextButton === undefined) delete next.controls.gamepad[player - 1][action];
  else next.controls.gamepad[player - 1][action] = [nextButton];
  return next;
}

function adjustGamepadComboButton(settings: GameSettings, player: 1 | 2, comboId: ButtonComboId, delta: number): GameSettings {
  const next = cloneSettings(settings);
  const current = next.controls.gamepadCombos[player - 1][comboId]?.[0];
  const nextButton = nextMenuConfigurableGamepadButton(current, delta);
  if (nextButton === undefined) delete next.controls.gamepadCombos[player - 1][comboId];
  else next.controls.gamepadCombos[player - 1][comboId] = [nextButton];
  return next;
}

function formatButtonComboLabel(comboId: ButtonComboId, scheme: ControlScheme = 'kore') {
  if (scheme !== 'beginner') return getButtonComboDefinition(comboId)?.label ?? comboId;
  return comboId
    .split('+')
    .map((button) => beginnerComboButtonLabels[button] ?? button)
    .join(' + ');
}

function nextMenuConfigurableGamepadButton(current: number | undefined, delta: number) {
  const direction = delta < 0 ? -1 : 1;
  if (current === undefined) return direction > 0 ? minConfigurableGamepadButton : maxConfigurableGamepadButton;
  if (direction < 0 && current <= minConfigurableGamepadButton) return undefined;
  if (direction > 0 && current >= maxConfigurableGamepadButton) return undefined;
  let candidate = Math.min(maxConfigurableGamepadButton, Math.max(minConfigurableGamepadButton, current + direction));
  while (menuReservedGamepadButtons.has(candidate) && candidate > minConfigurableGamepadButton && candidate < maxConfigurableGamepadButton) {
    candidate += direction;
  }
  if (menuReservedGamepadButtons.has(candidate)) return current;
  return candidate;
}

function formatKeyName(key: string) {
  return key
    .replace(/^Key/, '')
    .replace(/^Digit/, '')
    .replace(/^Numpad/, 'Num ')
    .replace('Arrow', '')
    .replace('Space', 'Spacebar')
    .replace('Escape', 'Esc');
}

function formatGamepadButtonName(button?: number) {
  if (button === undefined || button === null) return 'Unbound';
  return gamepadButtonPrompts[button]?.caption ?? `Gamepad button ${button}`;
}

function modeLabel(mode: MatchMode) {
  if (mode === 'ai') return 'Arcade';
  if (mode === 'cpuArcade') return 'CPU Arcade';
  if (mode === 'versusCpu') return '1P vs CPU';
  if (mode === 'local2p') return 'Local 2P';
  if (mode === 'training') return 'Training';
  if (mode === 'trainingOnline') return 'Training Online';
  if (mode === 'online') return 'Online';
  if (mode === 'ranked') return 'Ranked';
  if (mode === 'private') return 'Private';
  if (mode === 'custom') return 'Custom';
  if (mode === 'tournamentLocal') return 'Tournament';
  if (mode === 'tournamentOnline') return 'Online Tournament';
  if (mode === 'tournamentInfinite') return 'Infinite Tournament';
  return 'CPU vs CPU';
}

function chooseHitSfx(event: ImpactSparkEvent) {
  if (event.kind === 'block') {
    return event.moveInput === 'heavy' || event.moveInput === 'special' || event.damage >= 2 ? HIT_SFX.blockHeavy : HIT_SFX.blockLight;
  }

  if (event.kind === 'counterHit') return HIT_SFX.counterHit;

  if (event.launched) {
    return event.moveInput === 'special' || event.kiBurst ? HIT_SFX.bigLauncher : HIT_SFX.launcher;
  }

  if (event.moveInput === 'heavy') return HIT_SFX.heavy2;
  if (event.moveInput === 'kick') return HIT_SFX.kick3;
  if (event.moveInput === 'special') return HIT_SFX.special4;
  return HIT_SFX.punch1;
}

function makeStageFloorAudioSnapshot(fighter: FighterRuntime, lastRunAt = 0): StageFloorAudioSnapshot {
  return {
    state: fighter.state,
    y: fighter.position.y,
    dashForwardFrames: fighter.dashForwardFrames,
    x: fighter.position.x,
    z: fighter.position.z,
    lastRunAt
  };
}

function playStageFloorSfx(stage: StageDefinition, kind: StageFloorSoundKey, audioSettings: GameSettings['audio'], gain = 1) {
  if (typeof window === 'undefined' || audioSettings.muted || audioSettings.master <= 0 || audioSettings.sfx <= 0) return;
  const url = stage.floorSounds?.[kind];
  if (!url) return;
  const base = kind === 'run' ? 0.32 : kind === 'jump' ? 0.36 : kind === 'land' ? 0.48 : 0.42;
  const playbackRate = kind === 'run' ? 0.96 + Math.random() * 0.08 : kind === 'land' ? 0.92 : 1;
  playPooledSfx(url, clamp(audioSettings.master * audioSettings.sfx * base * gain, 0, 0.8), playbackRate);
}

function playHitSfx(event: ImpactSparkEvent, audioSettings: GameSettings['audio']) {
  if (typeof window === 'undefined' || audioSettings.muted || audioSettings.master <= 0 || audioSettings.sfx <= 0 || audioSettings.hitSfx <= 0) return;
  const isBlock = event.kind === 'block';
  const isLauncher = Boolean(event.launched);
  const gain = isBlock ? 0.82 : isLauncher ? 1 : 0.95;
  const volume = clamp(audioSettings.master * audioSettings.sfx * audioSettings.hitSfx * gain, 0, 1);
  const playbackRate = isBlock ? 0.96 : event.moveInput === 'special' ? 0.94 : 1;
  playPooledSfx(chooseHitSfx(event), volume, playbackRate);
}

function getCharacterVoicePool(character: CharacterDefinition, category: CharacterVoiceCategory, fallbackCategory?: CharacterVoiceCategory) {
  const voice = character.voice;
  const clips = voice?.[category] ?? [];
  if (clips.length > 0) return clips;
  return fallbackCategory ? voice?.[fallbackCategory] ?? [] : [];
}

function chooseCharacterVoiceSfx(character: CharacterDefinition, category: CharacterVoiceCategory, fallbackCategory?: CharacterVoiceCategory) {
  const voiceSfx = getCharacterVoicePool(character, category, fallbackCategory);
  if (voiceSfx.length === 0) return null;
  const key = `${character.id}:${category}`;
  let index = Math.floor(Math.random() * voiceSfx.length);
  const lastIndex = lastCharacterVoiceSfxIndices.get(key);
  if (voiceSfx.length > 1 && index === lastIndex) index = (index + 1 + Math.floor(Math.random() * (voiceSfx.length - 1))) % voiceSfx.length;
  lastCharacterVoiceSfxIndices.set(key, index);
  return voiceSfx[index];
}

function canPlayCharacterVoice(character: CharacterDefinition, category: CharacterVoiceCategory, cooldownMs: number) {
  if (typeof performance === 'undefined') return true;
  const key = `${character.id}:${category}`;
  const now = performance.now();
  const lastPlayedAt = lastCharacterVoicePlayedAt.get(key) ?? -Number.POSITIVE_INFINITY;
  if (now - lastPlayedAt < cooldownMs) return false;
  lastCharacterVoicePlayedAt.set(key, now);
  return true;
}

function playCharacterVoiceSfx(character: CharacterDefinition, category: CharacterVoiceCategory, audioSettings: GameSettings['audio'], volumeScale: number, fallbackCategory?: CharacterVoiceCategory) {
  if (typeof window === 'undefined' || audioSettings.muted || audioSettings.master <= 0 || audioSettings.voices <= 0) return false;
  const voiceSfx = chooseCharacterVoiceSfx(character, category, fallbackCategory);
  if (!voiceSfx) return false;
  const volume = clamp(audioSettings.master * audioSettings.voices * volumeScale, 0, 0.88);
  playPooledSfx(voiceSfx, volume, 1);
  return true;
}

function playCharacterAttackVoiceSfx(attacker: CharacterDefinition, event: ImpactSparkEvent, audioSettings: GameSettings['audio']) {
  if (typeof window === 'undefined' || audioSettings.muted || audioSettings.master <= 0 || audioSettings.voices <= 0) return;
  if (event.kind === 'block' || event.kind === 'clash') return;
  const category: CharacterVoiceCategory = event.tornado ? 'tornado' : event.launched ? 'launcher' : 'attackLand';
  const cooldown = category === 'attackLand' ? CHARACTER_ATTACK_VOICE_COOLDOWN_MS : CHARACTER_SPECIAL_VOICE_COOLDOWN_MS;
  if (!canPlayCharacterVoice(attacker, category, cooldown)) return;
  if (category === 'attackLand' && Math.random() > 0.32) return;
  playCharacterVoiceSfx(attacker, category, audioSettings, category === 'attackLand' ? 0.5 : 0.58, 'attackLand');
}

function playCharacterHurtVoiceSfx(defender: CharacterDefinition, event: ImpactSparkEvent, audioSettings: GameSettings['audio']) {
  if (typeof window === 'undefined' || audioSettings.muted || audioSettings.master <= 0 || audioSettings.voices <= 0) return;
  if (event.kind === 'block' || event.kind === 'clash' || event.comboHits !== 1) return;
  if (!canPlayCharacterVoice(defender, 'hit', CHARACTER_HURT_VOICE_COOLDOWN_MS)) return;
  playCharacterVoiceSfx(defender, 'hit', audioSettings, 0.56);
}

function playCharacterWinVoiceSfx(winner: CharacterDefinition, audioSettings: GameSettings['audio']) {
  return playCharacterVoiceSfx(winner, 'win', audioSettings, 0.68);
}

function playCharacterStageIntroVoiceSfx(character: CharacterDefinition, audioSettings: GameSettings['audio']) {
  return playCharacterVoiceSfx(character, 'stageIntro', audioSettings, 0.68, 'win');
}

function playNarutoShadowCloneVoiceSfx(character: CharacterDefinition, audioSettings: GameSettings['audio']) {
  if (typeof window === 'undefined' || audioSettings.muted || audioSettings.master <= 0 || audioSettings.voices <= 0) return;
  if (!canPlayCharacterVoice(character, 'shadowClone', CHARACTER_SPECIAL_VOICE_COOLDOWN_MS)) return;
  playCharacterVoiceSfx(character, 'shadowClone', audioSettings, 0.62);
}

function playRoundAnnouncerSfx(round: number, audioSettings: GameSettings['audio']) {
  if (typeof window === 'undefined' || audioSettings.muted || audioSettings.master <= 0 || audioSettings.voices <= 0) return false;
  const url = ROUND_ANNOUNCER_SFX[round - 1];
  if (!url) return false;
  const volume = clamp(audioSettings.master * audioSettings.voices * 0.92, 0, 1);
  playPooledSfx(url, volume, 1);
  return true;
}

function playChooseYourFighterSfx(audioSettings: GameSettings['audio']) {
  if (typeof window === 'undefined' || audioSettings.muted || audioSettings.master <= 0 || audioSettings.voices <= 0) return false;
  playPooledSfx(CHOOSE_YOUR_FIGHTER_SFX, clamp(audioSettings.master * audioSettings.voices * 0.92, 0, 1), 1);
  return true;
}

function playTrainingGreatSfx(audioSettings: GameSettings['audio']) {
  if (typeof window === 'undefined' || audioSettings.muted || audioSettings.master <= 0 || audioSettings.sfx <= 0) return false;
  playPooledSfx(TRAINING_GREAT_SFX, clamp(audioSettings.master * audioSettings.sfx * 0.9, 0, 1), 1);
  return true;
}

function getKiChargeSfxVolume(audioSettings: GameSettings['audio']) {
  if (audioSettings.muted || audioSettings.master <= 0 || audioSettings.sfx <= 0) return 0;
  return clamp(audioSettings.master * audioSettings.sfx * 0.16, 0, 0.24);
}

function getKiMaxChargeSfxVolume(audioSettings: GameSettings['audio']) {
  if (audioSettings.muted || audioSettings.master <= 0 || audioSettings.sfx <= 0) return 0;
  return clamp(audioSettings.master * audioSettings.sfx * 0.36, 0, 0.46);
}

function resolveSlotMove(character: CharacterDefinition, slot: AnimationSlot): MoveDefinition | null {
  if (slot.key === 'chargeKi') {
    return buildChargeKiEditorMove(character);
  }
  if (!isMoveSlotPose(slot.pose) && !slot.command) return null;
  const dataKey = getSlotDataKey(slot);
  const baseInput = isMoveSlotPose(slot.pose) ? slot.pose : commandPose(slot.command ?? slot.label);
  const baseMove = character.moves.find((move) => move.input === baseInput) ?? character.moves[0] ?? null;
  if (!baseMove) return null;
  const overrideKeys = [
    getLegacyRawButtonDataKey(dataKey),
    getLegacyBaseInputDataKey(dataKey),
    slot.command && dataKey === slot.key ? slot.command : undefined,
    baseMove.id,
    baseMove.input,
    dataKey
  ].filter(Boolean) as string[];
  const uniqueOverrideKeys = [...new Set(overrideKeys)];
  return uniqueOverrideKeys.reduce<MoveDefinition>((move, key) => {
    const override = character.moveOverrides?.[key];
    return override ? mergeMoveOverride(move, override) : move;
  }, baseMove);
}

function buildChargeKiEditorMove(character: CharacterDefinition): MoveDefinition {
  const base: MoveDefinition = {
    id: 'chargeKi',
    label: 'Charge Ki',
    input: 'special',
    command: 'chargeKi',
    notation: 'O',
    animationKey: 'chargeKi',
    comboKey: 'chargeKi',
    startupFrames: 14,
    activeFrames: 18,
    recoveryFrames: 16,
    damage: 0,
    blockDamage: 0,
    hitLevel: 'special',
    onBlockFrames: 0,
    onHitFrames: 0,
    onCounterHitFrames: 0,
    whiffRecoveryFrames: 0,
    range: 0.1,
    pushback: 0,
    blockPushback: 0,
    tracking: 'none',
    knockdown: false,
    hitbox: { offset: [0, 1, 0], size: [0, 0, 0] }
  };
  const override = character.moveOverrides?.chargeKi ?? character.moveOverrides?.['cmd:chargeKi'] ?? character.moveOverrides?.charge;
  return override ? mergeMoveOverride(base, override) : base;
}

function mergeMoveOverride(move: MoveDefinition, override: MoveOverride): MoveDefinition {
  return {
    ...move,
    ...override,
    hitbox: override.hitbox
      ? {
          offset: override.hitbox.offset ?? move.hitbox.offset,
          size: override.hitbox.size ?? move.hitbox.size
        }
      : move.hitbox
  };
}

function isMoveSlotPose(pose: PreviewPose): pose is MoveDefinition['input'] {
  return pose === 'jab' || pose === 'kick' || pose === 'heavy' || pose === 'special';
}

function getAnimationPreviewTotalFrames(slot: AnimationSlot, move: MoveDefinition | null, sequenceFrameCount: number) {
  if (move) return Math.max(1, move.startupFrames + move.activeFrames + move.recoveryFrames);
  if (slot.pose === 'chargeKi') return 48;
  return Math.max(1, sequenceFrameCount);
}

function getAnimationPreviewStepRate(slot: AnimationSlot, move: MoveDefinition | null, animationFps: number) {
  if (move || slot.pose === 'getup' || slot.pose === 'chargeKi') return 60;
  return Math.max(1, animationFps);
}

function getAnimationDurationFrames(sequenceFrameCount: number, animationFps: number) {
  if (sequenceFrameCount <= 0) return 1;
  return Math.max(1, Math.round((sequenceFrameCount / Math.max(1, animationFps)) * 60));
}

function getGetupActionForSlot(slot: AnimationSlot): Exclude<GetupAction, 'none'> | null {
  if (slot.pose !== 'getup') return null;
  if (slot.key === 'getupRollUp') return 'rollUp';
  if (slot.key === 'getupRollDown') return 'rollDown';
  if (slot.key === 'getupRollBack') return 'rollBack';
  return 'stand';
}

function getCharacterGetupFrames(character: CharacterDefinition, slot: AnimationSlot) {
  const action = getGetupActionForSlot(slot);
  if (!action) return 24;
  const override = character.getupFrameOverrides?.[action];
  if (Number.isFinite(override) && Number(override) > 0) return clamp(Math.round(Number(override)), 12, 96);
  const animationKey = (character.animationFrames?.[slot.key]?.length ?? 0) > 0
    ? slot.key
    : (character.animationFrames?.knockdown?.length ?? 0) > 0
      ? 'knockdown'
      : slot.key;
  const frameCount = character.animationFrames?.[animationKey]?.length ?? 0;
  const fps = character.animationFrameRates?.[animationKey] ?? character.animationFrameRates?.[slot.key] ?? character.animationFps ?? 8;
  if (frameCount > 0) return clamp(Math.round((frameCount / Math.max(1, fps)) * 60), 12, 72);
  return 24;
}

function formatFrameSummary(move: MoveDefinition | null) {
  if (!move) return 'No move data';
  const hitParts = [
    move.knockdown ? 'KD' : (move.launchHeight ?? 0) > 0 ? 'Launch' : signedFrame(move.onHitFrames),
    move.tornado ? 'T!' : null,
    move.endsInCrouch ? 'FC End' : null
  ].filter(Boolean);
  return `i${move.startupFrames} | ${capitalize(move.hitLevel)} | ${signedFrame(move.onBlockFrames)} OB | ${hitParts.join(' / ')} OH`;
}

function movePropertyBadges(move: MoveDefinition | null) {
  if (!move) return [];
  return [
    move.hitLevel === 'low' ? 'Low' : move.hitLevel === 'throw' || move.throwCapture ? 'Throw' : capitalize(move.hitLevel),
    (move.launchHeight ?? 0) > 0 ? 'Launcher' : null,
    move.tornado ? 'Tornado' : null,
    move.knockdown ? 'KD' : null,
    move.endsInCrouch ? 'FC End' : null,
    move.jumpBeforeMove ? 'Jump' : null,
    move.counterHit ? 'Counter Hit' : null,
    move.usesKi || move.kiBurst ? 'Ki' : null,
    move.tracking && move.tracking !== 'none' ? trackingBadgeLabel(move.tracking) : null
  ].filter((badge): badge is string => Boolean(badge));
}

function moveProjectileBadges(character: CharacterDefinition, slot: AnimationSlot) {
  const dataKey = getSlotDataKey(slot);
  const instances = character.moveProjectiles?.[dataKey] ?? [];
  if (instances.length === 0) return [];
  const hasBlast = instances.some((instance) => (
    instance.kind === 'blast' ||
    character.projectiles?.some((projectile) => projectile.id === instance.projectileId && projectile.kind === 'blast')
  ));
  const releaseGated = instances.some((instance) => instance.releaseGated);
  return [
    hasBlast ? 'Blast' : 'Projectile',
    releaseGated ? 'Charge/Hold' : null
  ].filter((badge): badge is string => Boolean(badge));
}

function trackingBadgeLabel(tracking: MoveTracking) {
  if (tracking === 'weakLeft') return 'Tracks Left';
  if (tracking === 'weakRight') return 'Tracks Right';
  return tracking === 'homing' ? 'Homing' : `${capitalize(tracking)} Tracking`;
}

function formatAnimationTimingSummary(frameCount: number, fps: number) {
  if (frameCount <= 0) return 'No frame data';
  return `${frameCount} sprite frames / ${Number(fps.toFixed(1))} FPS / ${getAnimationDurationFrames(frameCount, fps)}f loop`;
}

function formatMoveSlotLabel(slot: AnimationSlot, move: MoveDefinition | null) {
  return move?.label ?? slot.label;
}

function NoFrameDataPreview() {
  return (
    <div className="no-frame-data-preview" role="status" aria-label="No frame data">
      <span>NO FRAME DATA</span>
    </div>
  );
}

function signedFrame(value: number) {
  return value > 0 ? `+${value}` : `${value}`;
}

function capitalize(value: string) {
  return value.charAt(0).toUpperCase() + value.slice(1);
}

function ControlPanel({ title, rows }: { title: string; rows: string[] }) {
  return (
    <article className="control-panel">
      <h3>{title}</h3>
      {rows.map((row) => (
        <p key={row}>{row}</p>
      ))}
    </article>
  );
}

function CharacterViewer({
  roster,
  sourceRoster,
  onAnimationFramesChange,
  onAnimationSpeedChange,
  onAnimationScaleChange,
  onAnimationFrameScaleChange,
  onCharacterModelScaleChange,
  onMoveOverrideChange,
  onGetupFrameOverrideChange,
  onSpriteFrameEditChange,
  onEffectsChange,
  onCharacterMetadataChange,
  onImportComplete,
  onBack,
  onAnalytics
}: {
  roster: CharacterDefinition[];
  sourceRoster: CharacterDefinition[];
  onAnimationFramesChange: (characterId: string, animationKey: string, frames: string[]) => void;
  onAnimationSpeedChange: (characterId: string, animationKey: string, speed: number) => void;
  onAnimationScaleChange: (characterId: string, animationKey: string, size: AnimationScale) => void;
  onAnimationFrameScaleChange: (characterId: string, animationKey: string, frameIndex: number, size: AnimationScale) => void;
  onCharacterModelScaleChange: (characterId: string, size: CharacterModelScale) => void;
  onMoveOverrideChange: (characterId: string, moveKey: string, override: MoveOverride) => void;
  onGetupFrameOverrideChange: (characterId: string, action: Exclude<GetupAction, 'none'>, frames: number) => void;
  onSpriteFrameEditChange: (characterId: string, frameIndex: number, edit: SpriteFrameEdit) => void;
  onEffectsChange: (characterId: string, effects: CharacterEffectDefinition[], moveEffects: Record<string, MoveEffectInstance[]>) => void;
  onCharacterMetadataChange: (characterId: string, patch: CharacterMetadataPatch) => void;
  onImportComplete: (preferredCharacterId?: string) => Promise<void>;
  onBack: () => void;
  onAnalytics: AnalyticsCapture;
}) {
  const [activeId, setActiveId] = useState(roster[0]?.id ?? '');
  const [selectedAnimationKey, setSelectedAnimationKey] = useState(animationSlots[0].key);
  const [slotCategory, setSlotCategory] = useState<AnimationSlot['category'] | 'all'>('stance');
  const [slotSearch, setSlotSearch] = useState('');
  const [rotationTurn, setRotationTurn] = useState(0);
  const [viewMode, setViewMode] = useState<CharacterViewerViewMode>(() => readCharacterViewerViewMode());
  const [hideUnplayable, setHideUnplayable] = useState(true);
  const [zoom, setZoom] = useState(0.28);
  const [editorMode, setEditorMode] = useState<'browse' | 'animation' | 'sprite' | 'effectsLibrary' | 'moveEffects'>('browse');
  const [showImporter, setShowImporter] = useState(false);
  const [showSpriteSheetPreview, setShowSpriteSheetPreview] = useState(false);
  const [frameScaleMode, setFrameScaleMode] = useState(false);
  const frameRangeAnchorRef = useRef<number | null>(null);
  const [selectedSpriteFrameIndex, setSelectedSpriteFrameIndex] = useState(0);
  const [spriteFrameMeta, setSpriteFrameMeta] = useState<Record<string, SpriteFrameEdit>>({});
  const [spriteFrameMetaRefresh, setSpriteFrameMetaRefresh] = useState(0);
  const [manifestSaveStatus, setManifestSaveStatus] = useState<'idle' | 'saving' | 'saved' | 'error'>('idle');
  const [spriteSaveStatus, setSpriteSaveStatus] = useState<'idle' | 'saving' | 'saved' | 'error'>('idle');
  const [spriteSheetImportStatus, setSpriteSheetImportStatus] = useState<'idle' | 'working' | 'saved' | 'error'>('idle');
  const [spriteSheetDeleteStatus, setSpriteSheetDeleteStatus] = useState<'idle' | 'working' | 'saved' | 'error'>('idle');
  const [effectSaveStatus, setEffectSaveStatus] = useState<'idle' | 'saving' | 'saved' | 'error'>('idle');
  const [effectImportStatus, setEffectImportStatus] = useState<'idle' | 'working' | 'saved' | 'error'>('idle');
  const [effectFrameSaveStatus, setEffectFrameSaveStatus] = useState<'idle' | 'saving' | 'saved' | 'error'>('idle');
  const [moveSoundImportStatus, setMoveSoundImportStatus] = useState<'idle' | 'working' | 'saved' | 'error'>('idle');
  const [selectedEffectId, setSelectedEffectId] = useState('');
  const [selectedEffectFrameIndex, setSelectedEffectFrameIndex] = useState(0);
  const [effectTimelineFrame, setEffectTimelineFrame] = useState(0);
  const [animationPreviewPlaying, setAnimationPreviewPlaying] = useState(false);
  const [animationPreviewFrame, setAnimationPreviewFrame] = useState(0);
  const [showIdleGhost, setShowIdleGhost] = useState(false);
  const [showIdleGhostSideView, setShowIdleGhostSideView] = useState(false);
  const [unlockedScaleRatioKeys, setUnlockedScaleRatioKeys] = useState<Set<string>>(() => new Set());
  const [heightSheetStatus, setHeightSheetStatus] = useState<'idle' | 'generating' | 'error'>('idle');
  const [frameSheetStatus, setFrameSheetStatus] = useState<'idle' | 'generating' | 'error'>('idle');
  const [unusedFrameSheetStatus, setUnusedFrameSheetStatus] = useState<'idle' | 'generating' | 'error'>('idle');
  const [movesSheetStatus, setMovesSheetStatus] = useState<'idle' | 'generating' | 'error'>('idle');
  const [hdVoxelStatus, setHdVoxelStatus] = useState<'idle' | 'building' | 'saved' | 'error'>('idle');
  const [hdVoxelProgress, setHdVoxelProgress] = useState({ completed: 0, total: 0 });
  const [previewHdVoxels, setPreviewHdVoxels] = useState(false);
  const visibleRoster = useMemo(
    () => hideUnplayable ? roster.filter((character) => !character.unplayable) : roster,
    [hideUnplayable, roster]
  );
  const active = visibleRoster.find((character) => character.id === activeId) ?? visibleRoster[0] ?? roster[0];
  const sourceActive = sourceRoster.find((character) => character.id === active.id) ?? active;
  const isLocalDev = isLocalDevHost();
  const isEditingAnimation = editorMode === 'animation';
  const isEditingSpriteSheet = editorMode === 'sprite';
  const isEditingEffectsLibrary = editorMode === 'effectsLibrary';
  const isEditingMoveEffects = editorMode === 'moveEffects';
  const isCompactView = viewMode === 'compact';
  const selectedSlot = animationSlots.find((slot) => slot.key === selectedAnimationKey) ?? animationSlots[0];
  const frameCount =
    active.spriteFrameCount ??
    Math.max(0, ...Object.values(active.animationFrames ?? {}).flat().map(getFrameIndex)) + 1;
  const frameBank = useMemo(
    () => {
      const frames = Array.from({ length: frameCount }, (_, index) => framePath(active, index))
        .filter((path) => {
          const index = getFrameIndex(path);
          const edit = spriteFrameMeta[String(index)] ?? active.spriteFrameEdits?.[String(index)];
          return !edit?.hidden;
        });
      return frames.length > 0 ? frames : [framePath(active, 0)];
    },
    [active, frameCount, spriteFrameMeta]
  );
  const spriteSheets = useMemo(() => getCharacterSpriteSheets(active, frameCount), [active, frameCount]);
  const selectedSlotDataKey = getSlotDataKey(selectedSlot);
  const selectedFrames = active.animationFrames?.[selectedSlotDataKey] ?? [];
  const selectedPreviewFrameData = getViewerSlotFrameData(active, selectedSlot);
  const selectedPreviewAnimationKey = selectedPreviewFrameData.key;
  const selectedPreviewFrames = selectedPreviewFrameData.frames;
  const hasSelectedFrameData = selectedPreviewFrames.length > 0;
  const defaultFrames = sourceActive.animationFrames?.[selectedSlotDataKey] ?? selectedFrames;
  const selectedSpeed = active.animationFrameRates?.[selectedSlotDataKey] ?? active.animationFps ?? 8;
  const defaultSpeed = sourceActive.animationFrameRates?.[selectedSlotDataKey] ?? sourceActive.animationFps ?? active.animationFps ?? 8;
  const selectedAnimationScale = normalizeAnimationScale(active.animationScales?.[selectedSlotDataKey]);
  const selectedCharacterScale = getCharacterGlobalScale(active);
  const defaultCharacterScale = normalizeCharacterModelScale(undefined, sourceActive.scale ?? active.scale);
  const selectedFrameSet = new Set(selectedFrames);
  const selectedMove = resolveSlotMove(active, selectedSlot);
  const selectedMoveOverride = active.moveOverrides?.[selectedSlotDataKey] ?? {};
  const effects = active.effects ?? [];
  const selectedEffect = effects.find((effect) => effect.id === selectedEffectId) ?? effects[0] ?? null;
  const moveEffects = active.moveEffects ?? {};
  const selectedMoveEffectInstances = moveEffects[selectedSlotDataKey] ?? [];
  const selectedMoveTotalFrames = selectedMove ? selectedMove.startupFrames + selectedMove.activeFrames + selectedMove.recoveryFrames : 30;
  const selectedGetupAction = getGetupActionForSlot(selectedSlot);
  const selectedGetupFrames = selectedGetupAction ? getCharacterGetupFrames(active, selectedSlot) : 24;
  const defaultGetupFrames = selectedGetupAction ? getCharacterGetupFrames(sourceActive, selectedSlot) : 24;
  const selectedAnimationPreviewTotalFrames = selectedGetupAction
    ? selectedGetupFrames
    : getAnimationPreviewTotalFrames(selectedSlot, selectedMove, selectedPreviewFrames.length);
  const selectedAnimationDurationFrames = getAnimationDurationFrames(selectedFrames.length, selectedSpeed);
  const selectedAnimationPreviewStepRate = getAnimationPreviewStepRate(selectedSlot, selectedMove, selectedSpeed);
  const maxAnimationPreviewFrame = Math.max(0, selectedAnimationPreviewTotalFrames - 1);
  const clampedAnimationPreviewFrame = Math.min(maxAnimationPreviewFrame, Math.max(0, animationPreviewFrame));
  const hasIdleGhostFrame = (active.animationFrames?.idle?.length ?? 0) > 0;
  const activeAnimationSequenceIndex = selectedPreviewFrames.length > 0
    ? Math.min(selectedPreviewFrames.length - 1, Math.floor((clampedAnimationPreviewFrame / Math.max(1, selectedAnimationPreviewTotalFrames)) * selectedPreviewFrames.length))
    : -1;
  const activePreviewFrameIndex = getFrameIndex(selectedPreviewFrames[activeAnimationSequenceIndex] ?? selectedFrames[0] ?? '');
  const selectedFrameModeIndex = activePreviewFrameIndex >= 0 ? activePreviewFrameIndex : selectedSpriteFrameIndex;
  const selectedFrameModeAnimationKey = selectedPreviewAnimationKey || selectedSlotDataKey;
  const selectedAnimationFrameScale = normalizeAnimationScale(
    active.animationFrameScales?.[selectedFrameModeAnimationKey]?.[String(selectedFrameModeIndex)] ?? selectedAnimationScale
  );
  const selectedSizeScale = frameScaleMode ? selectedAnimationFrameScale : selectedAnimationScale;
  const selectedScaleRatioKey = `${active.id}:${frameScaleMode ? selectedFrameModeAnimationKey : selectedSlotDataKey}:${frameScaleMode ? selectedFrameModeIndex : 'animation'}`;
  const selectedScaleRatiosMatch = Math.abs(selectedSizeScale.width - selectedSizeScale.height) < 0.005;
  const selectedScaleRatioLocked = frameScaleMode && selectedScaleRatiosMatch && !unlockedScaleRatioKeys.has(selectedScaleRatioKey);
  const idleGhostFrame = active.animationFrames?.idle?.[0] ?? '';
  const sideViewCurrentFrame = selectedPreviewFrames[activeAnimationSequenceIndex] ?? selectedPreviewFrames[0] ?? selectedFrames[0] ?? '';
  const sideViewCurrentFrameIndex = getFrameIndex(sideViewCurrentFrame);
  const sideViewCurrentScale = normalizeAnimationScale(
    (sideViewCurrentFrameIndex >= 0 ? active.animationFrameScales?.[selectedPreviewAnimationKey]?.[String(sideViewCurrentFrameIndex)] : undefined) ??
    active.animationScales?.[selectedPreviewAnimationKey] ??
    active.animationScales?.[selectedSlotDataKey]
  );
  const sideViewIdleScale = {
    width: selectedCharacterScale.width,
    height: selectedCharacterScale.height
  };
  const sideViewCurrentRenderScale = {
    width: selectedCharacterScale.width * (sideViewCurrentScale.width ?? 1),
    height: selectedCharacterScale.height * (sideViewCurrentScale.height ?? 1)
  };
  const isIdleGhostSideView = showIdleGhost && showIdleGhostSideView && hasIdleGhostFrame && Boolean(idleGhostFrame && sideViewCurrentFrame);
  const variantBaseOptions = roster.filter((character) => character.id !== active.id && !isCharacterVariant(character));
  const activeVariantBase = variantBaseOptions.find((character) => character.id === active.variantOf) ?? variantBaseOptions[0] ?? null;
  const transformTargetOptions = roster.filter((character) => character.id !== active.id);
  const activeTransformTarget = transformTargetOptions.find((character) => character.id === active.transformCharacterId) ?? transformTargetOptions[0] ?? null;
  useEffect(() => {
    setAnimationPreviewPlaying(false);
    setAnimationPreviewFrame(0);
  }, [active.id, selectedSlotDataKey]);
  useEffect(() => {
    setAnimationPreviewFrame((frame) => Math.min(maxAnimationPreviewFrame, Math.max(0, frame)));
  }, [maxAnimationPreviewFrame]);
  useEffect(() => {
    if (!showIdleGhost || !hasIdleGhostFrame) setShowIdleGhostSideView(false);
  }, [hasIdleGhostFrame, showIdleGhost]);
  useEffect(() => {
    if (!isEditingAnimation || !frameScaleMode || selectedPreviewAnimationKey !== 'knockdown' || sideViewCurrentFrameIndex < 0) return;
    setSelectedSpriteFrameIndex(sideViewCurrentFrameIndex);
  }, [frameScaleMode, isEditingAnimation, selectedPreviewAnimationKey, sideViewCurrentFrameIndex]);
  useEffect(() => {
    if (!isEditingAnimation || !animationPreviewPlaying) return undefined;
    const timer = window.setInterval(() => {
      setAnimationPreviewFrame((frame) => (frame + 1) % Math.max(1, selectedAnimationPreviewTotalFrames));
    }, 1000 / selectedAnimationPreviewStepRate);
    return () => window.clearInterval(timer);
  }, [animationPreviewPlaying, isEditingAnimation, selectedAnimationPreviewStepRate, selectedAnimationPreviewTotalFrames]);
  useEffect(() => {
    if (!selectedEffect) return;
    const frameCount = selectedEffect.frames?.length ?? 0;
    if (frameCount > 0 && selectedEffectFrameIndex >= frameCount) setSelectedEffectFrameIndex(0);
  }, [selectedEffect, selectedEffectFrameIndex]);
  const previewCharacter = previewHdVoxels
    ? {
        ...active,
        voxelProfile: 'hd-image-source' as const,
        voxelFidelity: normalizeVoxelFidelity(active.voxelFidelity)
      }
    : active;
  const visibleSlots = animationSlots.filter((slot) => {
    const categoryMatches = slotCategory === 'all' || slot.category === slotCategory;
    const search = slotSearch.trim().toLowerCase();
    const searchMatches =
      !search ||
      slot.label.toLowerCase().includes(search) ||
      slot.command?.toLowerCase().includes(search) ||
      slot.notation.join(' ').toLowerCase().includes(search);
    return categoryMatches && searchMatches;
  });
  const moveGridColumnCount = slotCategory === 'stance' ? 4 : 1;
  const selectedSpriteFramePath = framePath(active, selectedSpriteFrameIndex);
  const selectedEditorSummary = isEditingSpriteSheet
    ? selectedSpriteFramePath
    : selectedGetupAction
      ? `${selectedGetupFrames} recovery frames`
      : selectedMove
        ? formatFrameSummary(selectedMove)
        : formatAnimationTimingSummary(selectedFrames.length, selectedSpeed);
  const updateAnimationPreviewFrame = (value: number) => {
    setAnimationPreviewPlaying(false);
    setAnimationPreviewFrame(Math.min(maxAnimationPreviewFrame, Math.max(0, Math.round(value))));
  };
  const jumpToAnimationSequenceFrame = (frame: string, sequenceIndex: number) => {
    const totalSequenceFrames = Math.max(1, selectedPreviewFrames.length);
    const nextFrame = Math.min(maxAnimationPreviewFrame, Math.floor((sequenceIndex / totalSequenceFrames) * selectedAnimationPreviewTotalFrames));
    setAnimationPreviewPlaying(false);
    setAnimationPreviewFrame(nextFrame);
    setSelectedSpriteFrameIndex(getFrameIndex(frame));
  };

  const cycleActiveCharacter = useCallback((direction: -1 | 1) => {
    if (visibleRoster.length <= 1) return;
    const currentIndex = Math.max(0, visibleRoster.findIndex((character) => character.id === active.id));
    const nextIndex = (currentIndex + direction + visibleRoster.length) % visibleRoster.length;
    const next = visibleRoster[nextIndex];
    if (next) setActiveId(next.id);
  }, [active.id, visibleRoster]);

  useEffect(() => {
    if (visibleRoster.some((character) => character.id === activeId)) return;
    if (visibleRoster[0]) setActiveId(visibleRoster[0].id);
  }, [activeId, visibleRoster]);

  const selectVisibleSlotAt = (index: number) => {
    const next = visibleSlots[index];
    if (!next) return;
    setSelectedAnimationKey(next.key);
    window.requestAnimationFrame(() => {
      document.querySelector<HTMLButtonElement>(`[data-viewer-slot-index="${index}"]`)?.focus();
    });
  };

  const handleMoveGridKeyDown = (event: ReactKeyboardEvent<HTMLDivElement>) => {
    const target = event.target as HTMLElement;
    if (['INPUT', 'SELECT', 'TEXTAREA'].includes(target.tagName)) return;
    if (visibleSlots.length === 0) return;
    const currentIndex = Math.max(0, visibleSlots.findIndex((slot) => slot.key === selectedAnimationKey));
    let nextIndex = currentIndex;

    if (event.key === 'ArrowLeft') nextIndex = currentIndex - 1;
    else if (event.key === 'ArrowRight') nextIndex = currentIndex + 1;
    else if (event.key === 'ArrowUp') nextIndex = currentIndex - moveGridColumnCount;
    else if (event.key === 'ArrowDown') nextIndex = currentIndex + moveGridColumnCount;
    else if (event.key === 'Home') nextIndex = 0;
    else if (event.key === 'End') nextIndex = visibleSlots.length - 1;
    else return;

    event.preventDefault();
    selectVisibleSlotAt(Math.max(0, Math.min(visibleSlots.length - 1, nextIndex)));
  };

  useEffect(() => {
    if (!active?.id) return;
    const firstSelectedIndex = getFrameIndex(selectedFrames[0] ?? '');
    if (firstSelectedIndex >= 0) setSelectedSpriteFrameIndex(firstSelectedIndex);
  }, [active.id, selectedAnimationKey]);

  useEffect(() => {
    const handleCharacterShoulderKeys = (event: KeyboardEvent) => {
      const target = event.target as HTMLElement | null;
      if (target?.isContentEditable || ['INPUT', 'SELECT', 'TEXTAREA'].includes(target?.tagName ?? '')) return;
      if (event.repeat) return;
      const key = event.key.toLowerCase();
      if (key === 'o') {
        event.preventDefault();
        cycleActiveCharacter(-1);
      } else if (key === 'p') {
        event.preventDefault();
        cycleActiveCharacter(1);
      }
    };
    window.addEventListener('keydown', handleCharacterShoulderKeys);
    return () => window.removeEventListener('keydown', handleCharacterShoulderKeys);
  }, [cycleActiveCharacter]);

  useEffect(() => {
    let mounted = true;
    setSpriteFrameMeta({});
    fetch(`/characters/${active.id}/frames/frames.json`)
      .then((response) => (response.ok ? response.json() : null))
      .then((data: { frames?: SpriteFrameEdit[] } | null) => {
        if (!mounted) return;
        const entries = Object.fromEntries(
          (data?.frames ?? [])
            .filter((frame) => Number.isFinite(frame.index) && Array.isArray(frame.box))
            .map((frame) => [String(frame.index), sanitizeSpriteFrameEdit(frame)])
        );
        setSpriteFrameMeta(entries);
      })
      .catch(() => {
        if (mounted) setSpriteFrameMeta({});
      });
    return () => {
      mounted = false;
    };
  }, [active.id, spriteFrameMetaRefresh]);

  useEffect(() => {
    if (!isLocalDev && editorMode !== 'browse') setEditorMode('browse');
  }, [editorMode, isLocalDev]);

  useEffect(() => {
    if (!selectedEffectId && effects[0]) setSelectedEffectId(effects[0].id);
    if (selectedEffectId && effects.length > 0 && !effects.some((effect) => effect.id === selectedEffectId)) {
      setSelectedEffectId(effects[0].id);
    }
  }, [effects, selectedEffectId]);

  useEffect(() => {
    if (editorMode !== 'animation') setShowSpriteSheetPreview(false);
  }, [editorMode, selectedAnimationKey, active.id]);

  useEffect(() => {
    frameRangeAnchorRef.current = null;
  }, [active.id, editorMode, selectedSlotDataKey]);

  useEffect(() => {
    debugLog(6, 'viewer active character and slot', {
      activeId: active.id,
      displayName: active.displayName,
      selectedAnimationKey,
      selectedSlotLabel: selectedSlot.label
    });
    debugLog(7, 'viewer effective animation selection', {
      characterId: active.id,
      animationKey: selectedSlotDataKey,
      previewAnimationKey: selectedPreviewAnimationKey,
      previewUsesFallback: selectedPreviewFrameData.usesFallback,
      selectedSlotKey: selectedSlot.key,
      effectiveFrames: selectedFrames.map(getFrameIndex),
      previewFrames: selectedPreviewFrames.map(getFrameIndex),
      defaultFrames: defaultFrames.map(getFrameIndex),
      effectiveFps: selectedSpeed,
      defaultFps: defaultSpeed
    });
  }, [active.id, active.displayName, defaultFrames, defaultSpeed, selectedAnimationKey, selectedFrames, selectedPreviewAnimationKey, selectedPreviewFrameData.usesFallback, selectedPreviewFrames, selectedSlot.key, selectedSlot.label, selectedSlotDataKey, selectedSpeed]);

  const updateSelectedFrames = (frames: string[]) => {
    onAnimationFramesChange(active.id, selectedSlotDataKey, frames);
  };

  const updateSelectedSpeed = (speed: number) => {
    if (!Number.isFinite(speed)) return;
    const normalized = Math.max(1, Math.min(24, Number(speed.toFixed(1))));
    onAnimationSpeedChange(active.id, selectedSlotDataKey, normalized);
  };

  const updateSelectedAnimationScale = (patch: AnimationScale) => {
    if (frameScaleMode) {
      onAnimationFrameScaleChange(active.id, selectedFrameModeAnimationKey, selectedFrameModeIndex, normalizeAnimationScale({
        ...selectedAnimationFrameScale,
        ...patch
      }));
      return;
    }
    onAnimationScaleChange(active.id, selectedSlotDataKey, normalizeAnimationScale({
      ...selectedAnimationScale,
      ...patch
    }));
  };

  const updateSelectedAnimationScaleAxis = (axis: 'width' | 'height', value: number) => {
    if (selectedScaleRatioLocked) {
      updateSelectedAnimationScale({ width: value, height: value });
      return;
    }
    updateSelectedAnimationScale(axis === 'width' ? { width: value } : { height: value });
  };

  const resetSelectedAnimationScale = () => {
    if (frameScaleMode) {
      onAnimationFrameScaleChange(active.id, selectedFrameModeAnimationKey, selectedFrameModeIndex, selectedAnimationScale);
      return;
    }
    onAnimationScaleChange(active.id, selectedSlotDataKey, { width: 1, height: 1 });
  };

  const updateSelectedCharacterScale = (patch: CharacterModelScale) => {
    onCharacterModelScaleChange(active.id, normalizeCharacterModelScale({
      ...selectedCharacterScale,
      ...patch
    }, active.scale));
  };

  const resetSelectedCharacterScale = () => {
    onCharacterModelScaleChange(active.id, defaultCharacterScale);
  };

  const resetSelectedAnimation = () => {
    updateSelectedFrames(defaultFrames);
    updateSelectedSpeed(defaultSpeed);
    if (selectedGetupAction) onGetupFrameOverrideChange(active.id, selectedGetupAction, defaultGetupFrames);
    resetSelectedAnimationScale();
  };

  const updateSelectedMoveOverride = (patch: MoveOverride) => {
    if (!selectedMove) return;
    onMoveOverrideChange(active.id, selectedSlotDataKey, {
      ...selectedMoveOverride,
      ...patch
    });
  };

  const updateSelectedGetupFrames = (value: string) => {
    if (!selectedGetupAction) return;
    const numeric = Number(value);
    if (!Number.isFinite(numeric)) return;
    onGetupFrameOverrideChange(active.id, selectedGetupAction, numeric);
  };

  const updateSelectedAnimationDurationFrames = (value: string) => {
    const numeric = Number(value);
    if (!Number.isFinite(numeric) || selectedFrames.length <= 0) return;
    const durationFrames = Math.max(1, Math.round(numeric));
    updateSelectedSpeed((selectedFrames.length / durationFrames) * 60);
  };

  const updateCharacterEffects = (
    nextEffects: CharacterEffectDefinition[] = effects,
    nextMoveEffects: Record<string, MoveEffectInstance[]> = moveEffects
  ) => {
    onEffectsChange(active.id, sanitizeEffects(nextEffects), sanitizeMoveEffects(canonicalizeRawButtonRecord(nextMoveEffects)));
  };

  const saveEffectsToDev = async (
    nextEffects: CharacterEffectDefinition[] = effects,
    nextMoveEffects: Record<string, MoveEffectInstance[]> = moveEffects
  ) => {
    setEffectSaveStatus('saving');
    try {
      const response = await fetch('/__kore/dev/save-character-effects', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          characterId: active.id,
          effects: sanitizeEffects(nextEffects),
          moveEffects: sanitizeMoveEffects(canonicalizeRawButtonRecord(nextMoveEffects))
        })
      });
      if (!response.ok) throw new Error(await response.text());
      updateCharacterEffects(nextEffects, nextMoveEffects);
      await onImportComplete(active.id);
      setEffectSaveStatus('saved');
      window.setTimeout(() => setEffectSaveStatus('idle'), 1800);
    } catch (error) {
      console.error('Failed to save character effects', error);
      setEffectSaveStatus('error');
    }
  };

  const importEffectSpriteSheet = async (file: File | undefined) => {
    if (!file || !isLocalDev) return;
    setEffectImportStatus('working');
    try {
      const result = await detectSpriteSheetFrames(file);
      const effectId = uniqueEffectId(active, file.name);
      const response = await fetch('/__kore/dev/import-effect-spritesheet', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          characterId: active.id,
          effectId,
          effectName: file.name.replace(/\.[^.]+$/, ''),
          sheetDataUrl: result.sheetDataUrl,
          frames: result.frames
        })
      });
      if (!response.ok) throw new Error(await response.text());
      const payload = await response.json() as { effect?: Partial<CharacterEffectDefinition> };
      const imported = sanitizeEffects([{ ...defaultCharacterEffect(effectId), ...(payload.effect ?? {}) }])[0];
      const nextEffects = sanitizeEffects([...effects.filter((effect) => effect.id !== imported.id), imported]);
      updateCharacterEffects(nextEffects, moveEffects);
      setSelectedEffectId(imported.id);
      setEffectImportStatus('saved');
      window.setTimeout(() => setEffectImportStatus('idle'), 1800);
    } catch (error) {
      console.error('Failed to import effect spritesheet', error);
      setEffectImportStatus('error');
    }
  };

  const importEffectSound = async (file: File | undefined, effectId: string) => {
    if (!file || !isLocalDev || !effectId) return;
    setEffectImportStatus('working');
    try {
      const dataUrl = await readFileAsDataUrl(file);
      const response = await fetch('/__kore/dev/import-effect-sound', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ characterId: active.id, effectId, fileName: file.name, dataUrl })
      });
      if (!response.ok) throw new Error(await response.text());
      const payload = await response.json() as { path?: string };
      const nextEffects = effects.map((effect) => (
        effect.id === effectId
          ? {
              ...effect,
              soundCues: [
                ...(effect.soundCues ?? []),
                {
                  id: uniqueCueId(effect),
                  name: file.name.replace(/\.[^.]+$/, ''),
                  path: payload.path ?? '',
                  frame: 0,
                  volume: 0.7,
                  pitch: 1,
                  pan: 0,
                  retrigger: false
                }
              ]
            }
          : effect
      ));
      updateCharacterEffects(nextEffects, moveEffects);
      setEffectImportStatus('saved');
      window.setTimeout(() => setEffectImportStatus('idle'), 1800);
    } catch (error) {
      console.error('Failed to import effect sound', error);
      setEffectImportStatus('error');
    }
  };

  const importMoveSound = async (file: File | undefined) => {
    if (!file || !isLocalDev || !selectedMove) return;
    setMoveSoundImportStatus('working');
    try {
      const dataUrl = await readFileAsDataUrl(file);
      const response = await fetch('/__kore/dev/import-move-sound', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ characterId: active.id, moveKey: selectedSlotDataKey, fileName: file.name, dataUrl })
      });
      if (!response.ok) throw new Error(await response.text());
      const payload = await response.json() as { path?: string };
      const currentCues = selectedMove.soundCues ?? [];
      const soundCues: EffectSoundCue[] = [
        ...currentCues,
        {
          id: uniqueSoundCueId(currentCues),
          name: file.name.replace(/\.[^.]+$/, ''),
          path: payload.path ?? '',
          frame: 0,
          volume: 0.72,
          pitch: 1,
          pan: 0,
          retrigger: false
        }
      ];
      updateSelectedMoveOverride({ soundCues });
      setMoveSoundImportStatus('saved');
      window.setTimeout(() => setMoveSoundImportStatus('idle'), 1800);
    } catch (error) {
      console.error('Failed to import move sound', error);
      setMoveSoundImportStatus('error');
    }
  };

  const addBlankEffect = () => {
    const effectId = uniqueEffectId(active, 'new-effect');
    const effect = defaultCharacterEffect(effectId);
    const nextEffects = sanitizeEffects([...effects, { ...effect, name: `Effect ${effects.length + 1}` }]);
    updateCharacterEffects(nextEffects, moveEffects);
    setSelectedEffectId(effectId);
  };

  const updateEffect = (effectId: string, patch: Partial<CharacterEffectDefinition>) => {
    const nextEffects = effects.map((effect) => (effect.id === effectId ? sanitizeEffects([{ ...effect, ...patch }])[0] : effect));
    updateCharacterEffects(nextEffects, moveEffects);
  };

  const saveEffectFrame = async (effectId: string, edit: SpriteFrameEdit, pngDataUrl: string) => {
    if (!isLocalDev || !effectId) return;
    setEffectFrameSaveStatus('saving');
    try {
      const frameIndex = Math.max(0, Math.round(edit.index));
      const response = await fetch('/__kore/dev/save-effect-frame', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          characterId: active.id,
          effectId,
          frameIndex,
          edit,
          pngDataUrl
        })
      });
      if (!response.ok) throw new Error(await response.text());
      const payload = await response.json() as { framePath?: string; edit?: SpriteFrameEdit };
      const framePathValue = payload.framePath ?? `/characters/${active.id}/effects/${effectId}/frames/frame-${frameIndex.toString().padStart(3, '0')}.png`;
      const nextEffects = effects.map((effect) => {
        if (effect.id !== effectId) return effect;
        const frames = [...(effect.frames ?? [])];
        frames[frameIndex] = framePathValue;
        return sanitizeEffects([{
          ...effect,
          frames,
          effectFrameEdits: {
            ...(effect.effectFrameEdits ?? {}),
            [String(frameIndex)]: payload.edit ?? edit
          }
        }])[0];
      });
      updateCharacterEffects(nextEffects, moveEffects);
      setEffectFrameSaveStatus('saved');
      window.setTimeout(() => setEffectFrameSaveStatus('idle'), 1800);
    } catch (error) {
      console.error('Failed to save effect frame', error);
      setEffectFrameSaveStatus('error');
    }
  };

  const deleteEffectFrame = async (effectId: string, frameIndex: number) => {
    if (!isLocalDev || !effectId) return;
    const effect = effects.find((item) => item.id === effectId);
    const frames = effect?.frames ?? [];
    if (!effect || frameIndex < 0 || frameIndex >= frames.length) return;
    setEffectFrameSaveStatus('saving');
    try {
      const response = await fetch('/__kore/dev/delete-effect-frame', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          characterId: active.id,
          effectId,
          frameIndex
        })
      });
      if (!response.ok) throw new Error(await response.text());
      const payload = await response.json() as {
        frames?: string[];
        effectFrameEdits?: Record<string, SpriteFrameEdit>;
      };
      const nextFrames = payload.frames ?? frames.filter((_, index) => index !== frameIndex);
      const nextEffects = effects.map((item) => (
        item.id === effectId
          ? sanitizeEffects([{
              ...item,
              frames: nextFrames,
              effectFrameEdits: payload.effectFrameEdits ?? {}
            }])[0]
          : item
      ));
      updateCharacterEffects(nextEffects, moveEffects);
      setSelectedEffectFrameIndex(Math.min(Math.max(0, nextFrames.length - 1), frameIndex));
      setEffectFrameSaveStatus('saved');
      window.setTimeout(() => setEffectFrameSaveStatus('idle'), 1800);
    } catch (error) {
      console.error('Failed to delete effect frame', error);
      setEffectFrameSaveStatus('error');
    }
  };

  const deleteEffect = (effectId: string) => {
    const nextEffects = effects.filter((effect) => effect.id !== effectId);
    const nextMoveEffects = Object.fromEntries(
      Object.entries(moveEffects)
        .map(([key, instances]) => [key, instances.filter((instance) => instance.effectId !== effectId)])
        .filter(([, instances]) => instances.length > 0)
    ) as Record<string, MoveEffectInstance[]>;
    updateCharacterEffects(nextEffects, nextMoveEffects);
    if (selectedEffectId === effectId) setSelectedEffectId(nextEffects[0]?.id ?? '');
  };

  const attachSelectedEffectToMove = (effectId: string) => {
    if (!effectId) return;
    const nextInstance: MoveEffectInstance = {
      id: uniqueMoveEffectInstanceId(selectedMoveEffectInstances, effectId),
      effectId,
      label: effects.find((effect) => effect.id === effectId)?.name,
      startFrame: 0,
      endFrame: selectedMoveTotalFrames,
      layer: selectedMoveEffectInstances.length,
      mirrorWithFacing: true,
      anchor: 'body',
      keyframes: [
        { frame: 0, position: [0, 0.15, 0.28], scale: [2.25, 2.25, 2.25], rotation: [0, 0, 0], opacity: 1, color: '#ffffff' },
        { frame: Math.max(1, selectedMoveTotalFrames), position: [0, 0.15, 0.28], scale: [2.25, 2.25, 2.25], rotation: [0, 0, 0], opacity: 1, color: '#ffffff' }
      ],
      soundCues: []
    };
    updateMoveEffectInstances([...selectedMoveEffectInstances, nextInstance]);
  };

  const updateMoveEffectInstances = (instances: MoveEffectInstance[]) => {
    const nextMoveEffects = {
      ...moveEffects,
      [selectedSlotDataKey]: sanitizeMoveEffects({ [selectedSlotDataKey]: instances })[selectedSlotDataKey] ?? []
    };
    if (nextMoveEffects[selectedSlotDataKey].length === 0) delete nextMoveEffects[selectedSlotDataKey];
    updateCharacterEffects(effects, nextMoveEffects);
  };

  const saveActiveManifest = async () => {
    setManifestSaveStatus('saving');
    try {
      const result = await saveCharacterManifestToDev(active);
      if (result.shouldRefresh) await onImportComplete(active.id);
      setManifestSaveStatus('saved');
      window.setTimeout(() => setManifestSaveStatus('idle'), 1800);
    } catch (error) {
      console.error('Failed to save character manifest', error);
      setManifestSaveStatus('error');
    }
  };

  const toggleSelectedScaleRatioLock = (locked: boolean) => {
    setUnlockedScaleRatioKeys((current) => {
      const next = new Set(current);
      if (locked) next.delete(selectedScaleRatioKey);
      else next.add(selectedScaleRatioKey);
      return next;
    });
    if (locked) {
      updateSelectedAnimationScale({
        width: selectedSizeScale.width,
        height: selectedSizeScale.width
      });
      return;
    }
    void saveActiveManifest();
  };

  const saveActiveMetadata = async (
    patch: CharacterMetadataPatch,
    failureLabel: string
  ) => {
    onCharacterMetadataChange(active.id, patch);
    if (!isLocalDev) return;
    setManifestSaveStatus('saving');
    try {
      const result = await saveCharacterManifestToDev({ ...active, ...patch });
      if (result.shouldRefresh) await onImportComplete(active.id);
      setManifestSaveStatus('saved');
      window.setTimeout(() => setManifestSaveStatus('idle'), 1800);
    } catch (error) {
      console.error(failureLabel, error);
      setManifestSaveStatus('error');
    }
  };

  const toggleActiveLocked = async () => {
    await saveActiveMetadata({ locked: !active.locked }, 'Failed to save character lock state');
  };

  const toggleActiveUnplayable = async (unplayable: boolean) => {
    await saveActiveMetadata({ unplayable }, 'Failed to save character playable state');
  };

  const toggleActiveVariant = async () => {
    if (active.variant) {
      await saveActiveMetadata({ variant: false, variantOf: '' }, 'Failed to save character variant state');
      return;
    }
    if (!activeVariantBase) return;
    await saveActiveMetadata({ variant: true, variantOf: activeVariantBase.id }, 'Failed to save character variant state');
  };

  const updateActiveVariantBase = async (variantOf: string) => {
    if (!variantOf || variantOf === active.id) return;
    await saveActiveMetadata({ variant: true, variantOf }, 'Failed to save character variant base');
  };

  const toggleActiveTransform = async () => {
    if (active.hasTransform) {
      await saveActiveMetadata({ hasTransform: false, transformCharacterId: '' }, 'Failed to save character transform state');
      return;
    }
    if (!activeTransformTarget) return;
    await saveActiveMetadata({ hasTransform: true, transformCharacterId: activeTransformTarget.id }, 'Failed to save character transform state');
  };

  const updateActiveTransformTarget = async (transformCharacterId: string) => {
    if (!transformCharacterId || transformCharacterId === active.id) return;
    await saveActiveMetadata({ hasTransform: true, transformCharacterId }, 'Failed to save character transform target');
  };

  const updateActiveDashDistance = async (dashDistance: number) => {
    const normalized = Number(clamp(Number(dashDistance) || 0.78, 0, 2.4).toFixed(2));
    await saveActiveMetadata({ stats: { ...active.stats, dashDistance: normalized } }, 'Failed to save character dash distance');
  };

  const importFaceCard = async (file: File | undefined) => {
    if (!file || !isLocalDev) return;
    setManifestSaveStatus('saving');
    try {
      const dataUrl = await readFileAsDataUrl(file);
      const response = await fetch('/__kore/dev/save-character-face-card', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          characterId: active.id,
          fileName: file.name,
          dataUrl
        })
      });
      if (!response.ok) throw new Error(await response.text());
      const payload = await response.json() as { path?: string };
      if (payload.path) onCharacterMetadataChange(active.id, { faceCardPath: payload.path });
      await onImportComplete(active.id);
      setManifestSaveStatus('saved');
      window.setTimeout(() => setManifestSaveStatus('idle'), 1800);
    } catch (error) {
      console.error('Failed to save character face card', error);
      setManifestSaveStatus('error');
    }
  };

  const rebuildHdVoxels = async () => {
    setHdVoxelStatus('building');
    setHdVoxelProgress({ completed: 0, total: frameCount });
    try {
      await saveHdVoxelsToDev(
        {
          ...active,
          voxelProfile: 'hd-image-source',
          voxelFidelity: normalizeVoxelFidelity(active.voxelFidelity)
        },
        (completed, total) => setHdVoxelProgress({ completed, total })
      );
      setPreviewHdVoxels(true);
      await onImportComplete(active.id);
      setHdVoxelStatus('saved');
      window.setTimeout(() => setHdVoxelStatus('idle'), 2200);
    } catch (error) {
      console.error('Failed to rebuild HD voxels', error);
      setHdVoxelStatus('error');
    }
  };

  const generateHeightSheet = async () => {
    if (!isLocalDev || heightSheetStatus === 'generating') return;
    const popup = window.open('', '_blank');
    if (popup) {
      popup.document.title = 'Generating Height Sheet';
      popup.document.body.style.margin = '0';
      popup.document.body.style.background = '#07090c';
      popup.document.body.style.color = '#f7f7f2';
      popup.document.body.style.fontFamily = 'system-ui, sans-serif';
      popup.document.body.innerHTML = '<main style="min-height:100vh;display:grid;place-items:center"><strong>Generating height sheet...</strong></main>';
    }
    setHeightSheetStatus('generating');
    try {
      const entries = roster.map((character) => {
        const frame = character.animationFrames?.idle?.[0] ?? framePath(character, 0);
        const frameIndex = getFrameIndex(frame);
        const globalScale = getCharacterGlobalScale(character);
        const idleScale = normalizeAnimationScale(
          character.animationFrameScales?.idle?.[String(frameIndex)] ??
          character.animationScales?.idle
        );
        return {
          characterId: character.id,
          displayName: character.displayName,
          frame: new URL(frame, window.location.href).href,
          frameIndex,
          renderScale: {
            width: Number((globalScale.width * idleScale.width).toFixed(4)),
            height: Number((globalScale.height * idleScale.height).toFixed(4))
          }
        };
      });
      const html = buildHeightSheetHtml(entries);
      const url = URL.createObjectURL(new Blob([html], { type: 'text/html' }));
      if (popup && !popup.closed) popup.location.href = url;
      else window.open(url, '_blank');
      window.setTimeout(() => URL.revokeObjectURL(url), 60000);
      setHeightSheetStatus('idle');
    } catch (error) {
      console.error('Failed to generate character height sheet', error);
      if (popup && !popup.closed) {
        popup.document.body.innerHTML = '<main style="min-height:100vh;display:grid;place-items:center;color:#ffb9b9;background:#07090c;font-family:system-ui,sans-serif"><strong>Height sheet failed.</strong></main>';
      }
      setHeightSheetStatus('error');
      window.setTimeout(() => setHeightSheetStatus('idle'), 2200);
    }
  };

  const buildFrameSheetCharacters = () => roster
    .filter((character) => !character.unplayable)
    .map((character) => {
      const characterFrameCount =
        character.spriteFrameCount ??
        Math.max(0, ...Object.values(character.animationFrames ?? {}).flat().map(getFrameIndex)) + 1;
      const globalScale = getCharacterGlobalScale(character);
      const animationEntries = Object.entries(character.animationFrames ?? {});
      const frames = Array.from({ length: characterFrameCount }, (_, frameIndex) => {
        const frame = framePath(character, frameIndex);
        const uses = animationEntries
          .filter(([, animationFrames]) => animationFrames.some((animationFrame) => getFrameIndex(animationFrame) === frameIndex))
          .map(([animationKey]) => animationKey);
        const scaleOptions = (uses.length ? uses : ['']).map((animationKey) => {
          const scale = normalizeAnimationScale(
            animationKey
              ? character.animationFrameScales?.[animationKey]?.[String(frameIndex)] ?? character.animationScales?.[animationKey]
              : undefined
          );
          return {
            animationKey: animationKey || 'unassigned',
            width: scale.width,
            height: scale.height,
            source: animationKey && character.animationFrameScales?.[animationKey]?.[String(frameIndex)]
              ? 'frame'
              : animationKey && character.animationScales?.[animationKey]
                ? 'animation'
                : 'global'
          };
        });
        const selectedScale = scaleOptions.find((scale) => scale.source === 'frame') ??
          scaleOptions.find((scale) => scale.source === 'animation') ??
          scaleOptions[0] ?? { animationKey: 'unassigned', width: 1, height: 1, source: 'global' };
        const uniqueScales = new Set(scaleOptions.map((scale) => `${scale.width}:${scale.height}:${scale.source}`));
        return {
          frameIndex,
          frame: new URL(frame, window.location.href).href,
          renderScale: {
            width: Number((globalScale.width * selectedScale.width).toFixed(4)),
            height: Number((globalScale.height * selectedScale.height).toFixed(4))
          },
          scaleLabel: `${selectedScale.animationKey} ${selectedScale.source}${uniqueScales.size > 1 ? ` +${uniqueScales.size - 1}` : ''}`
        };
      });
      return {
        characterId: character.id,
        displayName: character.displayName,
        frames
      };
    });

  const generateFrameComparisonSheet = async () => {
    if (!isLocalDev || frameSheetStatus === 'generating') return;
    const popup = window.open('', '_blank');
    if (popup) {
      popup.document.title = 'Generating Frame Comparison Sheet';
      popup.document.body.style.margin = '0';
      popup.document.body.style.background = '#07090c';
      popup.document.body.style.color = '#f7f7f2';
      popup.document.body.style.fontFamily = 'system-ui, sans-serif';
      popup.document.body.innerHTML = '<main style="min-height:100vh;display:grid;place-items:center"><strong>Generating frame comparison sheet...</strong></main>';
    }
    setFrameSheetStatus('generating');
    try {
      const html = buildFrameComparisonSheetHtml(buildFrameSheetCharacters());
      const url = URL.createObjectURL(new Blob([html], { type: 'text/html' }));
      if (popup && !popup.closed) popup.location.href = url;
      else window.open(url, '_blank');
      window.setTimeout(() => URL.revokeObjectURL(url), 60000);
      setFrameSheetStatus('idle');
    } catch (error) {
      console.error('Failed to generate frame comparison sheet', error);
      if (popup && !popup.closed) {
        popup.document.body.innerHTML = '<main style="min-height:100vh;display:grid;place-items:center;color:#ffb9b9;background:#07090c;font-family:system-ui,sans-serif"><strong>Frame comparison sheet failed.</strong></main>';
      }
      setFrameSheetStatus('error');
      window.setTimeout(() => setFrameSheetStatus('idle'), 2200);
    }
  };

  const buildUnusedFrameSheetCharacters = async (): Promise<UnusedFrameSheetCharacterEntry[]> => Promise.all(
    roster.map(async (character) => {
      const usedFrameIndices = new Set(
        Object.values(character.animationFrames ?? {})
          .flat()
          .map(getFrameIndex)
          .filter((index) => index >= 0)
      );
      const fallbackFrameCount =
        character.spriteFrameCount ??
        Math.max(0, ...Object.values(character.animationFrames ?? {}).flat().map(getFrameIndex)) + 1;
      const framesData = await fetch(`/characters/${character.id}/frames/frames.json`)
        .then((response) => (response.ok ? response.json() : null))
        .catch(() => null) as { frames?: SpriteFrameEdit[] } | null;
      const metadataByIndex = new Map(
        (framesData?.frames ?? [])
          .filter((frame) => Number.isFinite(frame.index))
          .map((frame) => [Math.max(0, Math.round(frame.index)), frame])
      );
      const frameIndices = metadataByIndex.size > 0
        ? [...metadataByIndex.keys()].sort((a, b) => a - b)
        : Array.from({ length: Math.max(0, fallbackFrameCount) }, (_, frameIndex) => frameIndex);
      return {
        characterId: character.id,
        displayName: character.displayName,
        totalFrames: frameIndices.length,
        usedFrames: usedFrameIndices.size,
        frames: frameIndices
          .filter((frameIndex) => !usedFrameIndices.has(frameIndex))
          .map((frameIndex) => {
            const meta = metadataByIndex.get(frameIndex);
            return {
              frameIndex,
              frame: new URL(framePath(character, frameIndex), window.location.href).href,
              sheetId: typeof meta?.sheetId === 'string' ? meta.sheetId : undefined,
              row: Number.isFinite(meta?.row) ? Number(meta?.row) : undefined
            };
          })
      };
    })
  );

  const generateUnusedFramesSheet = async () => {
    if (!isLocalDev || unusedFrameSheetStatus === 'generating') return;
    const popup = window.open('', '_blank');
    if (popup) {
      popup.document.title = 'Generating Unused Frames Sheet';
      popup.document.body.style.margin = '0';
      popup.document.body.style.background = '#07090c';
      popup.document.body.style.color = '#f7f7f2';
      popup.document.body.style.fontFamily = 'system-ui, sans-serif';
      popup.document.body.innerHTML = '<main style="min-height:100vh;display:grid;place-items:center"><strong>Generating unused frames sheet...</strong></main>';
    }
    setUnusedFrameSheetStatus('generating');
    try {
      const html = buildUnusedFramesSheetHtml(await buildUnusedFrameSheetCharacters());
      const url = URL.createObjectURL(new Blob([html], { type: 'text/html' }));
      if (popup && !popup.closed) popup.location.href = url;
      else window.open(url, '_blank');
      window.setTimeout(() => URL.revokeObjectURL(url), 60000);
      setUnusedFrameSheetStatus('idle');
    } catch (error) {
      console.error('Failed to generate unused frames sheet', error);
      if (popup && !popup.closed) {
        popup.document.body.innerHTML = '<main style="min-height:100vh;display:grid;place-items:center;color:#ffb9b9;background:#07090c;font-family:system-ui,sans-serif"><strong>Unused frames sheet failed.</strong></main>';
      }
      setUnusedFrameSheetStatus('error');
      window.setTimeout(() => setUnusedFrameSheetStatus('idle'), 2200);
    }
  };

  const buildMovesSheetCharacters = (): MovesSheetCharacterEntry[] => roster.map((character) => {
    const seenKeys = new Set<string>();
    const moveRows = animationSlots.flatMap((slot) => {
      const dataKey = getSlotDataKey(slot);
      const frames = character.animationFrames?.[dataKey] ?? [];
      if (frames.length === 0) return [];
      seenKeys.add(dataKey);
      const move = resolveSlotMove(character, slot);
      const frameRate = character.animationFrameRates?.[dataKey] ?? character.animationFps ?? 8;
      return [{
        animationKey: dataKey,
        slotKey: slot.key,
        label: formatMoveSlotLabel(slot, move),
        category: slot.category,
        notation: slot.notation,
        command: slot.command,
        frameRate,
        durationFrames: getAnimationDurationFrames(frames.length, frameRate),
        frameData: move ? formatFrameSummary(move) : formatAnimationTimingSummary(frames.length, frameRate),
        frames: frames.map((frame, sequenceIndex) => ({
          sequenceIndex,
          frameIndex: getFrameIndex(frame),
          frame: new URL(frame, window.location.href).href
        }))
      }];
    });
    const extraRows = Object.entries(character.animationFrames ?? {})
      .filter(([animationKey, frames]) => !seenKeys.has(animationKey) && frames.length > 0)
      .map(([animationKey, frames]) => {
        const frameRate = character.animationFrameRates?.[animationKey] ?? character.animationFps ?? 8;
        return {
          animationKey,
          slotKey: animationKey,
          label: animationKey,
          category: 'extra' as const,
          notation: [animationKey],
          frameRate,
          durationFrames: getAnimationDurationFrames(frames.length, frameRate),
          frameData: formatAnimationTimingSummary(frames.length, frameRate),
          frames: frames.map((frame, sequenceIndex) => ({
            sequenceIndex,
            frameIndex: getFrameIndex(frame),
            frame: new URL(frame, window.location.href).href
          }))
        };
      });
    const rows = [...moveRows, ...extraRows];
    const uniqueFrameCount = new Set(rows.flatMap((row) => row.frames.map((frame) => frame.frameIndex).filter((frameIndex) => frameIndex >= 0))).size;
    return {
      characterId: character.id,
      displayName: character.displayName,
      rows,
      uniqueFrameCount,
      categoryCounts: rows.reduce<Record<string, number>>((counts, row) => {
        counts[row.category] = (counts[row.category] ?? 0) + 1;
        return counts;
      }, {})
    };
  });

  const generateMovesSheet = async () => {
    if (!isLocalDev || movesSheetStatus === 'generating') return;
    const popup = window.open('', '_blank');
    if (popup) {
      popup.document.title = 'Generating Moves Sheet';
      popup.document.body.style.margin = '0';
      popup.document.body.style.background = '#07090c';
      popup.document.body.style.color = '#f7f7f2';
      popup.document.body.style.fontFamily = 'system-ui, sans-serif';
      popup.document.body.innerHTML = '<main style="min-height:100vh;display:grid;place-items:center"><strong>Generating moves sheet...</strong></main>';
    }
    setMovesSheetStatus('generating');
    try {
      const html = buildMovesSheetHtml(buildMovesSheetCharacters());
      const url = URL.createObjectURL(new Blob([html], { type: 'text/html' }));
      if (popup && !popup.closed) popup.location.href = url;
      else window.open(url, '_blank');
      window.setTimeout(() => URL.revokeObjectURL(url), 60000);
      setMovesSheetStatus('idle');
    } catch (error) {
      console.error('Failed to generate moves sheet', error);
      if (popup && !popup.closed) {
        popup.document.body.innerHTML = '<main style="min-height:100vh;display:grid;place-items:center;color:#ffb9b9;background:#07090c;font-family:system-ui,sans-serif"><strong>Moves sheet failed.</strong></main>';
      }
      setMovesSheetStatus('error');
      window.setTimeout(() => setMovesSheetStatus('idle'), 2200);
    }
  };

  const toggleFrame = (path: string) => {
    if (selectedFrameSet.has(path)) {
      updateSelectedFrames(selectedFrames.filter((frame) => frame !== path));
      return;
    }
    updateSelectedFrames([...selectedFrames, path]);
  };

  const selectFrameFromBank = (path: string, bankIndex: number, event: ReactMouseEvent<HTMLButtonElement>) => {
    setSelectedSpriteFrameIndex(getFrameIndex(path));
    const anchorIndex = frameRangeAnchorRef.current;

    if (event.shiftKey && anchorIndex !== null) {
      updateSelectedFrames(addFrameRangeToSelection(selectedFrames, frameBank, anchorIndex, bankIndex));
    } else {
      toggleFrame(path);
    }

    frameRangeAnchorRef.current = bankIndex;
  };

  const removeSelectedFrameAt = (index: number) => {
    updateSelectedFrames(selectedFrames.filter((_, frameIndex) => frameIndex !== index));
  };

  const appendDuplicateFrame = (path: string, event?: ReactMouseEvent<HTMLElement>) => {
    event?.preventDefault();
    updateSelectedFrames([...selectedFrames, path]);
  };

  const saveSpriteFrame = async (edit: SpriteFrameEdit, pngDataUrl: string) => {
    setSpriteSaveStatus('saving');
    try {
      const nextEdit = sanitizeSpriteFrameEdit({
        ...edit,
        index: selectedSpriteFrameIndex,
        path: selectedSpriteFramePath,
        revision: Date.now()
      });
      const response = await fetch('/__kore/dev/save-sprite-frame', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          characterId: active.id,
          frameIndex: selectedSpriteFrameIndex,
          edit: nextEdit,
          pngDataUrl
        })
      });
      if (!response.ok) throw new Error(await response.text());
      const fidelity = normalizeVoxelFidelity(active.voxelFidelity);
      await saveHdVoxelFramesToDev(
        {
          ...active,
          voxelProfile: 'hd-image-source',
          voxelFidelity: fidelity
        },
        [
          {
            frameIndex: selectedSpriteFrameIndex,
            payload: await buildHdVoxelPayload(pngDataUrl, fidelity, selectedSpriteFramePath, getSpriteFrameVoxelSizing(nextEdit))
          }
        ],
        fidelity
      );
      clearImageVoxelCacheForFrame(active.id, selectedSpriteFrameIndex);
      onSpriteFrameEditChange(active.id, selectedSpriteFrameIndex, nextEdit);
      setSpriteFrameMeta((current) => ({ ...current, [String(selectedSpriteFrameIndex)]: nextEdit }));
      setSpriteSaveStatus('saved');
      window.setTimeout(() => setSpriteSaveStatus('idle'), 1800);
    } catch (error) {
      console.error('Failed to save sprite frame', error);
      setSpriteSaveStatus('error');
    }
  };

  const createSpriteFrame = (edit: SpriteFrameEdit) => {
    const nextEdit = sanitizeSpriteFrameEdit(edit);
    onSpriteFrameEditChange(active.id, nextEdit.index, nextEdit);
    setSpriteFrameMeta((current) => ({ ...current, [String(nextEdit.index)]: nextEdit }));
    setSelectedSpriteFrameIndex(nextEdit.index);
    setSpriteSaveStatus('idle');
  };

  const importAdditionalSpriteSheet = async (file: File | undefined) => {
    if (!file || !isLocalDev) return;
    setSpriteSheetImportStatus('working');
    try {
      const result = await detectSpriteSheetFrames(file, { preferSpriteLikeComponents: true });
      const sheetId = uniqueSpriteSheetId(active, file.name);
      const response = await fetch('/__kore/dev/import-character-spritesheet', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          characterId: active.id,
          sheetId,
          sheetName: file.name,
          sheetDataUrl: result.sheetDataUrl,
          frames: result.frames
        })
      });
      if (!response.ok) throw new Error(await response.text());
      const payload = await response.json() as { firstFrameIndex?: number };
      await onImportComplete(active.id);
      setSpriteFrameMetaRefresh((value) => value + 1);
      setSelectedSpriteFrameIndex(Math.max(0, Math.round(Number(payload.firstFrameIndex) || frameCount)));
      setSpriteSheetImportStatus('saved');
      window.setTimeout(() => setSpriteSheetImportStatus('idle'), 2200);
    } catch (error) {
      console.error('Failed to append character spritesheet', error);
      setSpriteSheetImportStatus('error');
    }
  };

  const deleteCharacterSpriteSheet = async (sheetId: string) => {
    if (!isLocalDev || !sheetId) return;
    setSpriteSheetDeleteStatus('working');
    try {
      const response = await fetch('/__kore/dev/delete-character-spritesheet', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          characterId: active.id,
          sheetId
        })
      });
      if (!response.ok) throw new Error(await response.text());
      await onImportComplete(active.id);
      setSpriteFrameMetaRefresh((value) => value + 1);
      setSelectedSpriteFrameIndex(0);
      setSpriteSheetDeleteStatus('saved');
      window.setTimeout(() => setSpriteSheetDeleteStatus('idle'), 2200);
    } catch (error) {
      console.error('Failed to delete character spritesheet', error);
      setSpriteSheetDeleteStatus('error');
    }
  };

  const variantActionControls = isLocalDev ? (
    <>
      <button
        className="secondary-button"
        onClick={() => setShowImporter(true)}
        data-testid="open-character-importer"
      >
        <Upload size={18} />
        Import Character
      </button>
      <button
        className={`secondary-button ${active.locked ? 'active-tool' : ''}`}
        onClick={toggleActiveLocked}
        disabled={manifestSaveStatus === 'saving'}
        data-testid="toggle-character-lock"
      >
        <KeyRound size={18} />
        {active.locked ? 'Locked' : 'Unlocked'}
      </button>
      <label className={`viewer-flag-toggle ${active.unplayable ? 'is-on' : ''}`}>
        <input
          type="checkbox"
          checked={Boolean(active.unplayable)}
          onChange={(event) => void toggleActiveUnplayable(event.target.checked)}
          disabled={manifestSaveStatus === 'saving'}
          data-testid="toggle-character-unplayable"
        />
        <EyeOff size={18} />
        <span>Unplayable</span>
      </label>
      <button
        className={`secondary-button ${active.variant ? 'active-tool' : ''}`}
        onClick={toggleActiveVariant}
        disabled={manifestSaveStatus === 'saving' || (!active.variant && !activeVariantBase)}
        data-testid="toggle-character-variant"
      >
        <Users size={18} />
        {active.variant ? 'Variant' : 'Base'}
      </button>
      {active.variant && activeVariantBase && (
        <label className="variant-base-control">
          <span>Base</span>
          <select
            value={active.variantOf ?? activeVariantBase.id}
            onChange={(event) => void updateActiveVariantBase(event.target.value)}
            disabled={manifestSaveStatus === 'saving'}
          >
            {variantBaseOptions.map((character) => (
              <option key={character.id} value={character.id}>{character.displayName}</option>
            ))}
          </select>
        </label>
      )}
    </>
  ) : null;

  const devPreviewActionControls = isLocalDev ? (
    <>
      <button
        className={`secondary-button ${active.hasTransform ? 'active-tool' : ''}`}
        onClick={toggleActiveTransform}
        disabled={manifestSaveStatus === 'saving' || (!active.hasTransform && !activeTransformTarget)}
        data-testid="toggle-character-transform"
      >
        <Shuffle size={18} />
        {active.hasTransform ? 'Has Transform' : 'No Transform'}
      </button>
      {active.hasTransform && activeTransformTarget && (
        <label className="variant-base-control">
          <span>Transform</span>
          <select
            value={active.transformCharacterId ?? activeTransformTarget.id}
            onChange={(event) => void updateActiveTransformTarget(event.target.value)}
            disabled={manifestSaveStatus === 'saving'}
          >
            {transformTargetOptions.map((character) => (
              <option key={character.id} value={character.id}>{character.displayName}</option>
            ))}
          </select>
        </label>
      )}
      <label className="variant-base-control">
        <span>Dash Step</span>
        <input
          type="number"
          min="0"
          max="2.4"
          step="0.05"
          value={active.stats.dashDistance ?? 0.78}
          onChange={(event) => void updateActiveDashDistance(Number(event.target.value))}
          disabled={manifestSaveStatus === 'saving'}
          data-testid="character-dash-distance"
        />
      </label>
      <label className="secondary-button sprite-sheet-import-button">
        <Upload size={18} />
        Face Card
        <input
          type="file"
          accept="image/png,image/webp,image/jpeg"
          onChange={(event) => {
            void importFaceCard(event.target.files?.[0]);
            event.currentTarget.value = '';
          }}
        />
      </label>
      <button
        className={`secondary-button ${isEditingAnimation ? 'active-tool' : ''}`}
        onClick={() => setEditorMode((current) => (current === 'animation' ? 'browse' : 'animation'))}
        data-testid="toggle-animation-editor"
      >
        <Settings size={18} />
        {isEditingAnimation ? 'Browse Moves' : 'Edit Selected'}
      </button>
      <button
        className="secondary-button"
        onClick={() => setEditorMode('sprite')}
        data-testid="toggle-sprite-editor"
      >
        <Target size={18} />
        Edit Spritesheet
      </button>
      <button
        className={`secondary-button ${isEditingEffectsLibrary ? 'active-tool' : ''}`}
        onClick={() => setEditorMode((current) => (current === 'effectsLibrary' ? 'browse' : 'effectsLibrary'))}
        data-testid="toggle-effects-library"
      >
        <Eye size={18} />
        View Effects
      </button>
      <button
        className={`secondary-button ${isEditingMoveEffects ? 'active-tool' : ''}`}
        onClick={() => setEditorMode((current) => (current === 'moveEffects' ? 'browse' : 'moveEffects'))}
        data-testid="toggle-move-effects"
      >
        <Settings size={18} />
        Add Effects
      </button>
      <button
        className={`secondary-button ${showIdleGhost && hasIdleGhostFrame ? 'active-tool' : ''}`}
        onClick={() => {
          setShowIdleGhost((current) => !current);
          if (showIdleGhost) setShowIdleGhostSideView(false);
        }}
        disabled={!hasIdleGhostFrame}
        data-testid="toggle-idle-ghost"
        title={hasIdleGhostFrame ? 'Overlay the first idle frame behind the current preview' : 'No idle frames available'}
      >
        <Eye size={18} />
        {showIdleGhost && hasIdleGhostFrame ? 'Idle Ghost On' : 'Idle Ghost'}
      </button>
      {showIdleGhost && hasIdleGhostFrame && (
        <button
          className={`secondary-button ${showIdleGhostSideView ? 'active-tool' : ''}`}
          onClick={() => setShowIdleGhostSideView((current) => !current)}
          data-testid="toggle-idle-ghost-side-view"
          title="Show static idle/current frame comparison with pixel rulers"
        >
          <Ruler size={18} />
          {showIdleGhostSideView ? 'Side View On' : 'Side View'}
        </button>
      )}
      <button
        className={`secondary-button ${previewHdVoxels ? 'active-tool' : ''}`}
        onClick={() => setPreviewHdVoxels((current) => !current)}
        data-testid="toggle-hd-voxel-preview"
      >
        <Eye size={18} />
        {previewHdVoxels ? 'HD Preview On' : 'HD Preview'}
      </button>
      <button
        className="secondary-button"
        onClick={rebuildHdVoxels}
        disabled={hdVoxelStatus === 'building'}
        data-testid="rebuild-hd-voxels"
      >
        <Target size={18} />
        {hdVoxelStatus === 'building' ? 'Building HD' : 'Rebuild HD Voxels'}
      </button>
      <button
        className={`secondary-button ${hideUnplayable ? 'active-tool' : ''}`}
        onClick={() => setHideUnplayable((current) => !current)}
        aria-pressed={hideUnplayable}
        data-testid="hide-unplayable-toggle"
      >
        <EyeOff size={18} />
        Hide Unplayable
      </button>
    </>
  ) : null;

  const zoomActionControls = (
    <>
      <div className="zoom-controls" aria-label="Model zoom controls">
        <button aria-label="Zoom out" onClick={() => setZoom((value) => Math.max(0, value - 0.18))} data-testid="viewer-zoom-out">
          <ZoomOut size={18} />
        </button>
        <input
          aria-label="Zoom level"
          type="range"
          min="0"
          max="1"
          step="0.01"
          value={zoom}
          onChange={(event) => setZoom(Number(event.target.value))}
          data-testid="viewer-zoom-slider"
        />
        <button aria-label="Zoom in" onClick={() => setZoom((value) => Math.min(1, value + 0.18))} data-testid="viewer-zoom-in">
          <ZoomIn size={18} />
        </button>
      </div>
      <span>Drag to rotate. Scroll or pinch to zoom.</span>
    </>
  );
  const sheetActionControls = isLocalDev ? (
    <>
      <button
        className="secondary-button compact-button"
        onClick={() => void generateHeightSheet()}
        disabled={heightSheetStatus === 'generating'}
        data-testid="generate-height-sheet"
      >
        <Ruler size={18} />
        {heightSheetStatus === 'generating' ? 'Generating Height Sheet' : 'Generate Height Sheet'}
      </button>
      <button
        className="secondary-button compact-button"
        onClick={() => void generateFrameComparisonSheet()}
        disabled={frameSheetStatus === 'generating'}
        data-testid="generate-frame-sheet"
      >
        <List size={18} />
        {frameSheetStatus === 'generating' ? 'Generating Frame Sheet' : 'Generate Frame Sheet'}
      </button>
      <button
        className="secondary-button compact-button"
        onClick={() => void generateMovesSheet()}
        disabled={movesSheetStatus === 'generating'}
        data-testid="generate-moves-sheet"
      >
        <Gamepad2 size={18} />
        {movesSheetStatus === 'generating' ? 'Generating Moves Sheet' : 'Generate Moves Sheet'}
      </button>
      <button
        className="secondary-button compact-button"
        onClick={() => void generateUnusedFramesSheet()}
        disabled={unusedFrameSheetStatus === 'generating'}
        data-testid="generate-unused-frames-sheet"
      >
        <EyeOff size={18} />
        {unusedFrameSheetStatus === 'generating' ? 'Generating Unused Frames' : 'Generate Unused Frames Sheet'}
      </button>
    </>
  ) : null;
  const toggleViewMode = () => {
    setViewMode((current) => {
      const next = current === 'display' ? 'compact' : 'display';
      writeCharacterViewerViewMode(next);
      return next;
    });
  };
  const changeViewLabel = viewMode === 'display' ? 'Change View: Compact' : 'Change View: Display';

  if (showImporter && isLocalDev) {
    return (
      <CharacterImportScreen
        roster={roster}
        onBack={() => setShowImporter(false)}
        onImportComplete={async (characterId) => {
          await onImportComplete(characterId);
          setActiveId(characterId);
          setShowImporter(false);
        }}
      />
    );
  }

  return (
    <div className="viewer-screen">
      <div className="viewer-layout">
        <div className="roster-list compact loader-bar" aria-label="Character roster">
          {visibleRoster.map((character) => (
            <button
              key={character.id}
              className={`fighter-card viewer-character-card ${active.id === character.id ? 'is-selected' : ''}`}
              style={{ '--fighter-color': character.colors.primary } as CSSProperties}
              onClick={() => setActiveId(character.id)}
              aria-label={character.displayName}
              title={character.displayName}
              data-unplayable={Boolean(character.unplayable)}
            >
              <img src={characterPortraitPath(character)} alt="" />
            </button>
          ))}
        </div>
        <article className={`model-viewer-panel ${isCompactView && !isEditingSpriteSheet ? 'is-compact-view' : ''} ${isEditingSpriteSheet ? 'is-sprite-editing' : ''}`}>
          {!isEditingSpriteSheet && (
            <div className="model-viewer-preview-column">
              <div className={`model-viewer-stage ${hasSelectedFrameData ? '' : 'is-empty-preview'} ${isIdleGhostSideView ? 'is-side-view' : ''}`}>
                {hasSelectedFrameData ? isIdleGhostSideView ? (
                  <IdleGhostSideViewComparison
                    idleFrame={idleGhostFrame}
                    currentFrame={sideViewCurrentFrame}
                    currentLabel={selectedSlot.label}
                    idleScale={sideViewIdleScale}
                    currentScale={sideViewCurrentRenderScale}
                  />
                ) : (
                  <CharacterPreviewCanvas
                    character={previewCharacter}
                    pose={selectedSlot.pose}
                    animationKey={selectedPreviewAnimationKey}
                    previewMove={selectedMove}
                    previewEffects={effects}
                    previewEffectInstances={selectedMoveEffectInstances}
                    previewEffectFrame={isEditingAnimation ? clampedAnimationPreviewFrame : undefined}
                    rotationTurn={rotationTurn}
                    zoom={zoom}
                    preserveCameraFrame={isCompactView}
                    showIdleGhost={showIdleGhost && hasIdleGhostFrame}
                  />
                ) : (
                  <NoFrameDataPreview />
                )}
              </div>
              {isCompactView && (
                <div className="viewer-actions model-viewer-preview-actions">
                  <div className="viewer-action-row">
                    {isLocalDev && devPreviewActionControls}
                    {!isIdleGhostSideView && zoomActionControls}
                    {sheetActionControls}
                  </div>
                </div>
              )}
            </div>
          )}
          <div className="model-viewer-controls-column">
            <div className="viewer-actions">
              <div className="viewer-action-row">
                {!isEditingSpriteSheet && (
                  <>
                  <button className="secondary-button" onClick={() => setRotationTurn((value) => value + 1)}>
                    <Rotate3D size={18} />
                    Rotate
                  </button>
                  <button className="secondary-button" onClick={toggleViewMode} data-testid="change-character-view">
                    {changeViewLabel}
                  </button>
                  {isLocalDev && !isCompactView && devPreviewActionControls}
                  {variantActionControls}
                  {!isCompactView && !isIdleGhostSideView && zoomActionControls}
                  {!isCompactView && sheetActionControls}
                </>
              )}
              {isEditingSpriteSheet && (
                <button className="secondary-button active-tool" onClick={() => setEditorMode('browse')} data-testid="close-sprite-editor">
                  <Eye size={18} />
                  Browse Moves
                </button>
              )}
            </div>
            <div className="viewer-action-row editor-control-row">
              <div className="editing-title">
                <span>{isEditingSpriteSheet ? 'Editing Spritesheet' : isEditingAnimation ? 'Editing' : 'Selected'}</span>
                <strong>
                  <NotationGroup tokens={selectedSlot.notation} />
                  {isEditingSpriteSheet ? `Frame ${selectedSpriteFrameIndex}` : formatMoveSlotLabel(selectedSlot, selectedMove)}
                </strong>
                <small>{selectedEditorSummary}</small>
              </div>
              {isLocalDev && !isEditingAnimation && !isEditingSpriteSheet && !isEditingEffectsLibrary && !isEditingMoveEffects && (
                <div className="frame-picker-actions character-size-controls">
                  <label className="speed-control">
                    <span>Character Width</span>
                    <input
                      aria-label={`${active.displayName} character width scale`}
                      type="range"
                      min="0.25"
                      max="2.5"
                      step="0.01"
                      value={selectedCharacterScale.width}
                      onChange={(event) => updateSelectedCharacterScale({ width: Number(event.target.value) })}
                      data-testid="character-width-slider"
                    />
                    <input
                      aria-label={`${active.displayName} character width scale value`}
                      type="number"
                      min="0.25"
                      max="2.5"
                      step="0.01"
                      value={selectedCharacterScale.width}
                      onChange={(event) => updateSelectedCharacterScale({ width: Number(event.target.value) })}
                      data-testid="character-width-input"
                    />
                  </label>
                  <label className="speed-control">
                    <span>Character Height</span>
                    <input
                      aria-label={`${active.displayName} character height scale`}
                      type="range"
                      min="0.25"
                      max="2.5"
                      step="0.01"
                      value={selectedCharacterScale.height}
                      onChange={(event) => updateSelectedCharacterScale({ height: Number(event.target.value) })}
                      data-testid="character-height-slider"
                    />
                    <input
                      aria-label={`${active.displayName} character height scale value`}
                      type="number"
                      min="0.25"
                      max="2.5"
                      step="0.01"
                      value={selectedCharacterScale.height}
                      onChange={(event) => updateSelectedCharacterScale({ height: Number(event.target.value) })}
                      data-testid="character-height-input"
                    />
                  </label>
                  <button className="secondary-button compact-button" onClick={resetSelectedCharacterScale} data-testid="character-size-reset">
                    Reset Character Size
                  </button>
                </div>
              )}
              {(isEditingAnimation || isEditingEffectsLibrary || isEditingMoveEffects) && (
                <div className="frame-picker-actions">
                  {isEditingAnimation && (
                    <>
                      <button
                        type="button"
                        className="secondary-button compact-button animation-preview-toggle"
                        onClick={() => setAnimationPreviewPlaying((current) => !current)}
                        data-testid="animation-preview-toggle"
                      >
                        {animationPreviewPlaying ? <Pause size={14} /> : <Play size={14} />}
                        {animationPreviewPlaying ? 'Pause Preview' : 'Play Preview'}
                      </button>
                      <label className="speed-control animation-frame-control">
                        <span>Frame</span>
                        <input
                          aria-label={`${selectedSlot.label} preview frame`}
                          type="range"
                          min="0"
                          max={maxAnimationPreviewFrame}
                          step="1"
                          value={clampedAnimationPreviewFrame}
                          onChange={(event) => updateAnimationPreviewFrame(Number(event.target.value))}
                          data-testid="animation-preview-frame-slider"
                        />
                        <input
                          aria-label={`${selectedSlot.label} preview frame value`}
                          type="number"
                          min="0"
                          max={maxAnimationPreviewFrame}
                          step="1"
                          value={clampedAnimationPreviewFrame}
                          onChange={(event) => updateAnimationPreviewFrame(Number(event.target.value))}
                          data-testid="animation-preview-frame-input"
                        />
                      </label>
                      <label className="speed-control">
                        <span>FPS</span>
                        <input
                          aria-label={`${selectedSlot.label} animation speed`}
                          type="range"
                          min="1"
                          max="24"
                          step="0.5"
                          value={selectedSpeed}
                          onChange={(event) => updateSelectedSpeed(Number(event.target.value))}
                          data-testid="animation-speed-slider"
                        />
                        <input
                          aria-label={`${selectedSlot.label} animation speed value`}
                          type="number"
                          min="1"
                          max="24"
                          step="0.5"
                          value={selectedSpeed}
                          onChange={(event) => updateSelectedSpeed(Number(event.target.value))}
                          data-testid="animation-speed-input"
                        />
                      </label>
                      <label className="speed-control">
                        <span>Width</span>
                        <input
                          aria-label={`${selectedSlot.label} animation width scale`}
                          type="range"
                          min="0.1"
                          max="10"
                          step="0.001"
                          value={selectedSizeScale.width}
                          onChange={(event) => updateSelectedAnimationScaleAxis('width', Number(event.target.value))}
                          data-testid="animation-width-slider"
                        />
                        <input
                          aria-label={`${selectedSlot.label} animation width scale value`}
                          type="number"
                          min="0.1"
                          max="10"
                          step="0.001"
                          value={selectedSizeScale.width}
                          onChange={(event) => updateSelectedAnimationScaleAxis('width', Number(event.target.value))}
                          data-testid="animation-width-input"
                        />
                      </label>
                      <label className="speed-control">
                        <span>Height</span>
                        <input
                          aria-label={`${selectedSlot.label} animation height scale`}
                          type="range"
                          min="0.1"
                          max="10"
                          step="0.001"
                          value={selectedSizeScale.height}
                          onChange={(event) => updateSelectedAnimationScaleAxis('height', Number(event.target.value))}
                          data-testid="animation-height-slider"
                        />
                        <input
                          aria-label={`${selectedSlot.label} animation height scale value`}
                          type="number"
                          min="0.1"
                          max="10"
                          step="0.001"
                          value={selectedSizeScale.height}
                          onChange={(event) => updateSelectedAnimationScaleAxis('height', Number(event.target.value))}
                          data-testid="animation-height-input"
                        />
                      </label>
                      {frameScaleMode ? (
                        <label className="sprite-sheet-toggle frame-ratio-toggle">
                          <input
                            type="checkbox"
                            checked={selectedScaleRatioLocked}
                            onChange={(event) => toggleSelectedScaleRatioLock(event.target.checked)}
                            data-testid="animation-scale-ratio-lock"
                          />
                          <span>Lock W/H</span>
                        </label>
                      ) : null}
                      <label className="speed-control">
                        <span>Position</span>
                        <input
                          aria-label={`${selectedSlot.label} animation horizontal position`}
                          type="range"
                          min="-6"
                          max="6"
                          step="0.01"
                          value={selectedSizeScale.offsetX}
                          onChange={(event) => updateSelectedAnimationScale({ offsetX: Number(event.target.value) })}
                          data-testid="animation-position-slider"
                        />
                        <input
                          aria-label={`${selectedSlot.label} animation horizontal position value`}
                          type="number"
                          min="-6"
                          max="6"
                          step="0.01"
                          value={selectedSizeScale.offsetX}
                          onChange={(event) => updateSelectedAnimationScale({ offsetX: Number(event.target.value) })}
                          data-testid="animation-position-input"
                        />
                      </label>
                      <button className="secondary-button compact-button" onClick={() => updateSelectedFrames([...selectedFrames].reverse())}>
                        Reverse
                      </button>
                      <button className="secondary-button compact-button" onClick={resetSelectedAnimationScale}>
                        {frameScaleMode ? 'Reset Frame Size' : 'Reset Size'}
                      </button>
                      {frameScaleMode ? (
                        <>
                          <button
                            className={`secondary-button compact-button ${selectedSizeScale.flipX ? 'active-tool' : ''}`}
                            onClick={() => updateSelectedAnimationScale({ flipX: !selectedSizeScale.flipX })}
                            data-testid="animation-frame-flip-x"
                          >
                            Flip X
                          </button>
                          <button
                            className={`secondary-button compact-button ${selectedSizeScale.flipY ? 'active-tool' : ''}`}
                            onClick={() => updateSelectedAnimationScale({ flipY: !selectedSizeScale.flipY })}
                            data-testid="animation-frame-flip-y"
                          >
                            Flip Y
                          </button>
                        </>
                      ) : null}
                      <label className="sprite-sheet-toggle frame-mode-toggle">
                        <input
                          type="checkbox"
                          checked={frameScaleMode}
                          onChange={(event) => setFrameScaleMode(event.target.checked)}
                        />
                        <span>Frame mode</span>
                      </label>
                      <button className="secondary-button compact-button" onClick={resetSelectedAnimation}>
                        Reset
                      </button>
                      <label className="sprite-sheet-toggle">
                        <input
                          type="checkbox"
                          checked={showSpriteSheetPreview}
                          onChange={(event) => setShowSpriteSheetPreview(event.target.checked)}
                        />
                        <span>Show spritesheet</span>
                      </label>
                    </>
                  )}
                  <button
                    className="secondary-button compact-button dev-save-button"
                    onClick={isEditingEffectsLibrary || isEditingMoveEffects ? () => saveEffectsToDev() : saveActiveManifest}
                    disabled={manifestSaveStatus === 'saving' || effectSaveStatus === 'saving'}
                    data-testid="save-character-manifest"
                  >
                    <Save size={14} />
                    {manifestSaveStatus === 'saving' || effectSaveStatus === 'saving' ? 'Saving' : 'Save JSON'}
                  </button>
                  {(manifestSaveStatus !== 'idle' || effectSaveStatus !== 'idle') && (
                    <span className={`manifest-save-status is-${manifestSaveStatus}`}>
                      {manifestSaveStatus === 'saved' || effectSaveStatus === 'saved'
                        ? 'Saved to manifest'
                        : manifestSaveStatus === 'error' || effectSaveStatus === 'error'
                          ? 'Save failed'
                          : 'Writing'}
                    </span>
                  )}
                  {hdVoxelStatus !== 'idle' && (
                    <span className={`manifest-save-status is-${hdVoxelStatus === 'saved' ? 'saved' : hdVoxelStatus === 'error' ? 'error' : 'saving'}`}>
                      {hdVoxelStatus === 'building'
                        ? `HD ${hdVoxelProgress.completed}/${hdVoxelProgress.total}`
                        : hdVoxelStatus === 'saved'
                          ? 'HD voxels saved'
                          : 'HD build failed'}
                    </span>
                  )}
                </div>
              )}
            </div>
          </div>
          {isEditingSpriteSheet ? (
            <SpriteSheetFrameEditor
              character={active}
              frameBank={frameBank}
              spriteSheets={spriteSheets}
              frameMeta={spriteFrameMeta}
              selectedFrameIndex={selectedSpriteFrameIndex}
              selectedFrames={selectedFrames}
              selectedFrameSet={selectedFrameSet}
              saveStatus={spriteSaveStatus}
              importStatus={spriteSheetImportStatus}
              deleteStatus={spriteSheetDeleteStatus}
              onSelectFrame={setSelectedSpriteFrameIndex}
              onToggleFrame={toggleFrame}
              onCreateFrame={createSpriteFrame}
              onSave={saveSpriteFrame}
              onImportSpriteSheet={importAdditionalSpriteSheet}
              onDeleteSpriteSheet={deleteCharacterSpriteSheet}
            />
          ) : isEditingEffectsLibrary ? (
            <EffectsLibraryEditor
              character={active}
              effects={effects}
              selectedEffect={selectedEffect}
              selectedFrameIndex={selectedEffectFrameIndex}
              importStatus={effectImportStatus}
              saveStatus={effectSaveStatus}
              frameSaveStatus={effectFrameSaveStatus}
              onSelectEffect={setSelectedEffectId}
              onSelectFrame={setSelectedEffectFrameIndex}
              onAddBlankEffect={addBlankEffect}
              onDeleteEffect={deleteEffect}
              onUpdateEffect={updateEffect}
              onImportSpriteSheet={importEffectSpriteSheet}
              onImportSound={importEffectSound}
              onSaveFrame={saveEffectFrame}
              onDeleteFrame={deleteEffectFrame}
              onSave={() => saveEffectsToDev()}
            />
          ) : isEditingMoveEffects ? (
            <MoveEffectsEditor
              character={previewCharacter}
              selectedSlot={selectedSlot}
              animationKey={selectedPreviewAnimationKey}
              hasFrameData={hasSelectedFrameData}
              previewMove={selectedMove}
              effects={effects}
              instances={selectedMoveEffectInstances}
              timelineFrame={effectTimelineFrame}
              totalFrames={selectedMoveTotalFrames}
              onTimelineFrameChange={setEffectTimelineFrame}
              onAttachEffect={attachSelectedEffectToMove}
              onUpdateInstances={updateMoveEffectInstances}
            />
          ) : isEditingAnimation ? (
            <section className="frame-picker inline-frame-editor" aria-label="Animation frame picker">
              {selectedGetupAction && (
                <GetupTimingEditor
                  action={selectedGetupAction}
                  frames={selectedGetupFrames}
                  onChange={updateSelectedGetupFrames}
                />
              )}
              {!selectedMove && !selectedGetupAction && (
                <AnimationTimingEditor
                  label={selectedSlot.label}
                  frameCount={selectedFrames.length}
                  fps={selectedSpeed}
                  durationFrames={selectedAnimationDurationFrames}
                  onDurationChange={updateSelectedAnimationDurationFrames}
                  onFpsChange={(value) => updateSelectedSpeed(Number(value))}
                />
              )}
              {selectedMove && (
                <>
                  <FrameDataEditor move={selectedMove} onChange={updateSelectedMoveOverride} />
                  <section className="frame-data-editor" aria-label="Move sound editor">
                    <header>
                      <span>Move Sounds</span>
                      <strong>{selectedMove.soundCues?.length ?? 0} cues</strong>
                      <small>{selectedSlotDataKey}</small>
                    </header>
                    <div className="effects-editor-toolbar">
                      {isLocalDev && (
                        <label className="secondary-button compact-button file-button">
                          <Upload size={14} />
                          Add Sound
                          <input type="file" accept="audio/wav,audio/mpeg,audio/mp3,audio/ogg,audio/webm" onChange={(event) => importMoveSound(event.target.files?.[0])} />
                        </label>
                      )}
                      {moveSoundImportStatus !== 'idle' && <small className={`manifest-save-status is-${moveSoundImportStatus === 'error' ? 'error' : moveSoundImportStatus === 'saved' ? 'saved' : 'saving'}`}>{moveSoundImportStatus}</small>}
                    </div>
                    <EffectSoundCueList
                      cues={selectedMove.soundCues}
                      onChange={(soundCues) => updateSelectedMoveOverride({ soundCues })}
                    />
                  </section>
                </>
              )}
              {showSpriteSheetPreview && active.spriteSheetPath && (
                <div className="sprite-sheet-stage">
                  <span>{active.spriteSheetPath}</span>
                  <img className="sprite-sheet-preview" src={active.spriteSheetPath} alt={`${active.displayName} sprite sheet`} />
                </div>
              )}
              <AnimationFrameColorStrip
                frames={selectedPreviewFrames}
                activeSequenceIndex={activeAnimationSequenceIndex}
                previewFrame={clampedAnimationPreviewFrame}
                totalFrames={selectedAnimationPreviewTotalFrames}
                onSelectFrame={jumpToAnimationSequenceFrame}
              />
              <div className="selected-frame-strip" aria-label="Selected frames">
                {selectedFrames.map((frame, index) => (
                  <div
                    key={`${frame}-${index}`}
                    className={`selected-frame-card ${frameScaleMode && getFrameIndex(frame) === selectedSpriteFrameIndex ? 'active' : ''}`}
                    title={frameScaleMode
                      ? `Frame ${getFrameIndex(frame)}. Click to select for frame sizing. Right-click to duplicate it at the end.`
                      : `Frame ${getFrameIndex(frame)}. Click to remove this occurrence. Right-click to duplicate it at the end.`}
                  >
                    <button
                      type="button"
                      className="selected-frame-thumb"
                      onClick={() => {
                        if (frameScaleMode) jumpToAnimationSequenceFrame(frame, index);
                        else removeSelectedFrameAt(index);
                      }}
                      onContextMenu={(event) => appendDuplicateFrame(frame, event)}
                    >
                      <img src={frame} alt={`Selected frame ${getFrameIndex(frame)}`} />
                      <span>{getFrameIndex(frame)}</span>
                    </button>
                    <button type="button" className="remove-frame-button" title="Remove this occurrence" onClick={() => removeSelectedFrameAt(index)}>
                      Remove
                    </button>
                  </div>
                ))}
              </div>
              <small className="frame-bank-hint">Click to toggle one frame. Shift-click to add a range.</small>
              <div className="frame-bank" aria-label="All extracted frames">
                {frameBank.map((frame, bankIndex) => (
                  <button
                    key={frame}
                    className={selectedFrameSet.has(frame) ? 'active' : ''}
                    onClick={(event) => selectFrameFromBank(frame, bankIndex, event)}
                    onContextMenu={(event) => appendDuplicateFrame(frame, event)}
                    data-testid={`animation-frame-bank-${getFrameIndex(frame)}`}
                    aria-label={`Frame ${getFrameIndex(frame)}${selectedFrameSet.has(frame) ? ', selected' : ''}`}
                    title={`Frame ${getFrameIndex(frame)}. Click to add/remove. Shift-click to add a range. Right-click to append a duplicate.`}
                  >
                    <img src={frame} alt={`Frame ${getFrameIndex(frame)}`} loading="lazy" />
                    <span>{getFrameIndex(frame)}</span>
                  </button>
                ))}
              </div>
            </section>
          ) : (
            <div
              className={`animation-grid ${slotCategory === 'stance' ? 'is-stance-grid' : 'is-command-grid'}`}
              aria-label="Animation previews"
              tabIndex={0}
              onKeyDown={handleMoveGridKeyDown}
            >
              <div className="command-toolbar">
                <CommandCategorySelect value={slotCategory} onChange={setSlotCategory} />
                <input
                  aria-label="Search move slots"
                  placeholder="Search notation"
                  value={slotSearch}
                  onChange={(event) => setSlotSearch(event.target.value)}
                />
              </div>
              {visibleSlots.map((option, index) => {
                const move = resolveSlotMove(active, option);
                const label = formatMoveSlotLabel(option, move);
                const optionDataKey = getSlotDataKey(option);
                const optionFrameCount = active.animationFrames?.[optionDataKey]?.length ?? 0;
                const optionSpeed = active.animationFrameRates?.[optionDataKey] ?? active.animationFps ?? 8;
                return (
                  <button
                    key={option.key}
                    className={selectedSlot.key === option.key ? 'active' : ''}
                    onClick={() => setSelectedAnimationKey(option.key)}
                    title={label}
                    data-viewer-slot-index={index}
                    data-testid={`viewer-pose-${option.key}`}
                  >
                    <NotationGroup tokens={option.notation} />
                    {label}
                    <small>{move ? formatFrameSummary(move) : formatAnimationTimingSummary(optionFrameCount, optionSpeed)}</small>
                  </button>
                );
              })}
            </div>
          )}
          </div>
        </article>
      </div>
      <button className="secondary-button" onClick={() => {
        onAnalytics('navigation_clicked', { destination: 'menu', source: 'viewer_back' });
        onBack();
      }}>
        <Home size={18} />
        Back
      </button>
    </div>
  );
}

type FrameComparisonMetrics = {
  image: HTMLImageElement;
  naturalWidth: number;
  naturalHeight: number;
  bounds: {
    left: number;
    top: number;
    width: number;
    height: number;
  };
};

type HeightSheetEntry = {
  characterId: string;
  displayName: string;
  frame: string;
  frameIndex: number;
  renderScale: {
    width: number;
    height: number;
  };
};

type FrameSheetCharacterEntry = {
  characterId: string;
  displayName: string;
  frames: Array<{
    frameIndex: number;
    frame: string;
    renderScale: {
      width: number;
      height: number;
    };
    scaleLabel: string;
  }>;
};

type UnusedFrameSheetCharacterEntry = {
  characterId: string;
  displayName: string;
  totalFrames: number;
  usedFrames: number;
  frames: Array<{
    frameIndex: number;
    frame: string;
    sheetId?: string;
    row?: number;
  }>;
};

type MovesSheetCharacterEntry = {
  characterId: string;
  displayName: string;
  uniqueFrameCount: number;
  categoryCounts: Record<string, number>;
  rows: Array<{
    animationKey: string;
    slotKey: string;
    label: string;
    category: AnimationSlot['category'] | 'extra';
    notation: NotationToken[];
    command?: string;
    frameRate: number;
    durationFrames: number;
    frameData: string;
    frames: Array<{
      sequenceIndex: number;
      frameIndex: number;
      frame: string;
    }>;
  }>;
};

function useFrameComparisonMetrics(src: string) {
  const [metrics, setMetrics] = useState<FrameComparisonMetrics | null>(null);

  useEffect(() => {
    let cancelled = false;
    setMetrics(null);
    if (!src) return undefined;
    void loadImage(src)
      .then((image) => {
        if (cancelled) return;
        setMetrics({
          image,
          naturalWidth: image.naturalWidth || image.width || 1,
          naturalHeight: image.naturalHeight || image.height || 1,
          bounds: getOpaqueImageBounds(image)
        });
      })
      .catch(() => {
        if (!cancelled) setMetrics(null);
      });
    return () => {
      cancelled = true;
    };
  }, [src]);

  return metrics;
}

function formatSignedPixels(value: number) {
  return value > 0 ? `+${value}px` : `${value}px`;
}

function CroppedComparisonFrame({
  metrics,
  alt,
  scale
}: {
  metrics: FrameComparisonMetrics | null;
  alt: string;
  scale: { width: number; height: number };
}) {
  const canvasRef = useRef<HTMLCanvasElement | null>(null);
  const width = Math.max(1, Math.round(metrics?.bounds.width ?? 1));
  const height = Math.max(1, Math.round(metrics?.bounds.height ?? 1));

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas || !metrics) return;
    const context = canvas.getContext('2d');
    if (!context) return;
    const { image, bounds } = metrics;
    context.clearRect(0, 0, width, height);
    context.imageSmoothingEnabled = false;
    context.drawImage(
      image,
      bounds.left,
      bounds.top,
      bounds.width,
      bounds.height,
      0,
      0,
      width,
      height
    );
  }, [height, metrics, width]);

  return (
    <canvas
      ref={canvasRef}
      className="side-frame-sprite"
      width={width}
      height={height}
      aria-label={alt}
      role="img"
      style={{
        '--frame-scale-x': scale.width,
        '--frame-scale-y': scale.height
      } as CSSProperties}
    />
  );
}

function IdleGhostSideViewComparison({
  idleFrame,
  currentFrame,
  currentLabel,
  idleScale,
  currentScale
}: {
  idleFrame: string;
  currentFrame: string;
  currentLabel: string;
  idleScale: { width: number; height: number };
  currentScale: { width: number; height: number };
}) {
  const idleMetrics = useFrameComparisonMetrics(idleFrame);
  const currentMetrics = useFrameComparisonMetrics(currentFrame);
  const idleWidthScale = idleScale.width ?? 1;
  const idleHeightScale = idleScale.height ?? 1;
  const widthScale = currentScale.width ?? 1;
  const heightScale = currentScale.height ?? 1;
  const idleHeight = Math.round((idleMetrics?.bounds.height ?? 0) * idleHeightScale);
  const idleWidth = Math.round((idleMetrics?.bounds.width ?? 0) * idleWidthScale);
  const currentHeight = Math.round((currentMetrics?.bounds.height ?? 0) * heightScale);
  const currentWidth = Math.round((currentMetrics?.bounds.width ?? 0) * widthScale);
  const targetHeight = idleHeight || currentHeight;
  const heightDelta = currentHeight && targetHeight ? currentHeight - targetHeight : 0;
  const frameIndex = getFrameIndex(currentFrame);
  const heightState = heightDelta > 0 ? 'too tall' : heightDelta < 0 ? 'too short' : 'matched';

  return (
    <div className="idle-ghost-side-view" data-testid="idle-ghost-side-view">
      <section className="idle-ghost-side-panel idle-reference-panel" aria-label="Idle reference frame">
        <header>
          <span>idle ref</span>
          <small>{idleHeight ? `idle foot-head ${idleHeight}px` : 'measuring idle'}</small>
        </header>
        <div className="side-frame-ruler">
          <div className="side-ruler side-ruler-idle" aria-hidden="true" />
          <span className="side-ruler-label side-ruler-label-idle">{idleHeight ? `idle foot-head ${idleHeight}px` : 'idle foot-head'}</span>
          <span className="side-baseline" aria-hidden="true" />
          <CroppedComparisonFrame
            metrics={idleMetrics}
            alt="Idle reference frame"
            scale={{ width: idleWidthScale, height: idleHeightScale }}
          />
        </div>
        <footer>
          <span>{idleWidth || '--'}px wide</span>
          <span>{idleHeight || '--'}px foot-head</span>
          <span>{idleWidthScale.toFixed(2)}w {idleHeightScale.toFixed(2)}h scale</span>
        </footer>
      </section>

      <section className="idle-ghost-side-panel current-frame-panel" aria-label="Current animation frame">
        <header>
          <span>{currentLabel} frame {frameIndex >= 0 ? frameIndex.toString().padStart(3, '0') : '--'}</span>
          <small>{widthScale.toFixed(2)}w {heightScale.toFixed(2)}h scale</small>
        </header>
        <div className="side-frame-ruler">
          <div className="side-ruler side-ruler-current" aria-hidden="true" />
          <span className="side-ruler-label side-ruler-label-target">target box {targetHeight || '--'}px</span>
          <span className="side-ruler-label side-ruler-label-current">
            {currentHeight ? `${formatSignedPixels(heightDelta)} ${heightState}` : 'measuring current'}
          </span>
          <span className="side-baseline" aria-hidden="true" />
          <CroppedComparisonFrame
            metrics={currentMetrics}
            alt={`${currentLabel} comparison frame`}
            scale={{ width: widthScale, height: heightScale }}
          />
        </div>
        <footer>
          <span>{currentWidth || '--'}px wide</span>
          <span>{currentHeight || '--'}px foot-head</span>
          <span>idle {idleWidth || '--'}px wide</span>
        </footer>
      </section>
    </div>
  );
}

