type TrainingButtonHistoryEntry = {
  id: number;
  signature: string;
  tokens: string[];
  frames: number;
};

const TRAINING_BUTTON_HISTORY_LIMIT = 18;

function getTrainingButtonHistoryTokens(input: InputFrame) {
  const tokens: string[] = [];
  const vertical = input.up ? 'up' : input.down ? 'down' : '';
  const horizontal = input.right ? 'right' : input.left ? 'left' : '';
  const directionToken =
    vertical === 'up' && horizontal === 'right' ? '↗' :
    vertical === 'up' && horizontal === 'left' ? '↖' :
    vertical === 'down' && horizontal === 'right' ? '↘' :
    vertical === 'down' && horizontal === 'left' ? '↙' :
    horizontal === 'right' ? '→' :
    horizontal === 'left' ? '←' :
    vertical === 'up' ? '↑' :
    vertical === 'down' ? '↓' :
    '';
  if (directionToken) tokens.push(directionToken);
  if (input.dashForward) tokens.push('Dash F');
  if (input.dashBack) tokens.push('Back Hop');
  if (input.sidestepUp) tokens.push('SS↑');
  if (input.sidestepDown) tokens.push('SS↓');
  if (input.sidewalkUp) tokens.push('Walk↑');
  if (input.sidewalkDown) tokens.push('Walk↓');
  if (input.jump) tokens.push('Jump');
  if (input.block) tokens.push('Block');
  if (input.charge) tokens.push('Charge');
  if (input.jab) tokens.push('1');
  if (input.heavy) tokens.push('2');
  if (input.kick) tokens.push('3');
  if (input.special) tokens.push('4');
  return tokens;
}

function getTrainingButtonHistorySignature(input: InputFrame) {
  return getTrainingButtonHistoryTokens(input).join('|');
}

function TrainingButtonHistory({ entries }: { entries: TrainingButtonHistoryEntry[] }) {
  const visibleEntries = entries.slice(0, TRAINING_BUTTON_HISTORY_LIMIT);
  return (
    <aside className="training-button-history" data-testid="training-button-history" aria-label="Training button history">
      <header>
        <span>Input History</span>
      </header>
      <div className="training-button-history-list">
        {visibleEntries.length === 0 ? (
          <div className="training-button-history-empty">Neutral</div>
        ) : visibleEntries.map((entry, index) => (
          <div
            key={entry.id}
            className={`training-button-history-row ${index === 0 ? 'latest' : ''}`}
            data-testid={`training-button-history-row-${index}`}
          >
            <div className="training-button-history-tokens">
              {entry.tokens.map((token) => (
                <span key={`${entry.id}:${token}`}>{token}</span>
              ))}
            </div>
            <small>{entry.frames}f</small>
          </div>
        ))}
      </div>
    </aside>
  );
}

function ClashOverlay({ match }: { match: MatchSnapshot }) {
  const clash = match.clashState;
  if (!clash || clash.status === 'none') return null;
  const p1Progress = clash.p1.completedFrame !== null ? clash.sequence.length : clash.p1.progress;
  const p2Progress = clash.p2.completedFrame !== null ? clash.sequence.length : clash.p2.progress;
  const resultText =
    clash.status === 'result'
      ? clash.winnerSlot
        ? `${clash.winnerSlot === 1 ? match.fighters[0].character.displayName : match.fighters[1].character.displayName} Wins`
        : 'Draw'
      : clash.status === 'intro'
        ? 'Ki Clash'
        : 'Match the sequence';
  return (
    <div className={`clash-overlay ${clash.status}`} aria-live="assertive">
      <div className="clash-vignette" />
      <div className="clash-panel">
        <span className="clash-eyebrow">{clash.status === 'result' ? 'Result' : 'Struggle'}</span>
        <strong>{resultText}</strong>
        {clash.status !== 'intro' && (
          <div className="clash-sequence" aria-label="Clash quick time sequence">
            {clash.sequence.map((button, index) => (
              <span key={`${clash.id}-${button}-${index}`}>{clashButtonLabels[button]}</span>
            ))}
          </div>
        )}
        <div className="clash-progress">
          <ClashProgress name={match.fighters[0].character.displayName} progress={p1Progress} total={clash.sequence.length} failed={clash.p1.failed} />
          <ClashProgress name={match.fighters[1].character.displayName} progress={p2Progress} total={clash.sequence.length} failed={clash.p2.failed} />
        </div>
        {clash.status === 'result' && clash.damage > 0 && <small>{clash.damage} clash damage</small>}
      </div>
    </div>
  );
}

function TimeStopOverlay({ match }: { match: MatchSnapshot }) {
  const timeStop = match.timeStop;
  if (!timeStop) return null;
  const owner = match.fighters[timeStop.ownerSlot - 1];
  return (
    <div className="time-stop-overlay" aria-live="assertive" data-owner-slot={timeStop.ownerSlot}>
      <div className="time-stop-pulse" />
      <div className="time-stop-callout">
        <small>{owner.character.displayName}</small>
        <strong>Star Platinum: The World</strong>
      </div>
    </div>
  );
}

function ClashProgress({ name, progress, total, failed }: { name: string; progress: number; total: number; failed: boolean }) {
  return (
    <div className={`clash-progress-row ${failed ? 'failed' : ''}`}>
      <span>{name}</span>
      <div>
        {Array.from({ length: total }, (_, index) => (
          <i key={index} className={index < progress ? 'filled' : ''} />
        ))}
      </div>
    </div>
  );
}

export function FightHud({ match, hudScale, onlineWins, playerNames, presentationMirrored = false }: { match: MatchSnapshot; hudScale: number; onlineWins?: OnlineWins; playerNames?: readonly [string | undefined, string | undefined]; presentationMirrored?: boolean }) {
  const [p1, p2] = match.fighters;
  const leftFighter = presentationMirrored ? p2 : p1;
  const rightFighter = presentationMirrored ? p1 : p2;
  const leftWins = presentationMirrored ? onlineWins?.[1] : onlineWins?.[0];
  const rightWins = presentationMirrored ? onlineWins?.[0] : onlineWins?.[1];
  const leftName = (presentationMirrored ? playerNames?.[1] : playerNames?.[0]) || leftFighter.character.displayName;
  const rightName = (presentationMirrored ? playerNames?.[0] : playerNames?.[1]) || rightFighter.character.displayName;
  const timerText = formatFightTimer(match, true);
  const timerDigits = /^\d+$/.test(timerText) ? timerText.split('') : null;
  return (
    <div className="fight-hud" style={{ '--hud-scale': hudScale } as CSSProperties}>
      <HealthBar fighter={leftFighter} align="left" displayName={leftName} onlineWins={leftWins} />
      <div className="round-box" data-testid="fight-hud-timer" aria-label={`Time ${timerText}`}>
        <div className="round-box-value">
          {timerDigits ? timerDigits.map((digit, index) => (
            <img
              key={`${digit}-${index}`}
              className="round-box-digit"
              src={`/ui/fight-hud/timer-digits/${digit}.png`}
              alt=""
              aria-hidden="true"
              data-testid={`fight-hud-timer-digit-${index}`}
            />
          )) : (
            <img
              className="round-box-infinity"
              src="/ui/fight-hud/timer-infinity.png"
              alt=""
              aria-hidden="true"
              data-testid="fight-hud-timer-infinity"
            />
          )}
        </div>
        <img className="round-box-frame" src="/ui/fight-hud/timer-frame.png" alt="" aria-hidden="true" />
        <span className="visually-hidden">{timerText}</span>
      </div>
      <HealthBar fighter={rightFighter} align="right" displayName={rightName} onlineWins={rightWins} />
    </div>
  );
}

function formatFightTimer(match: MatchSnapshot, rounded = false) {
  if (match.mode === 'training' || match.mode === 'trainingOnline' || match.roundTime <= 0) return '∞';
  return rounded ? String(Math.ceil(match.timer)) : match.timer.toFixed(2);
}

function ImpactScreenFlashLayer({ events, enabled, reducedMotion }: { events: ImpactSparkEvent[]; enabled: boolean; reducedMotion: boolean }) {
  if (!enabled || events.length === 0) return null;
  return (
    <div className={`impact-screen-flash-layer${reducedMotion ? ' reduced-motion' : ''}`} aria-hidden="true">
      {events.slice(-4).map((event) => (
        <div key={`impact-flash-${event.id}`} className={`impact-screen-flash ${resolveImpactFeedbackTone(event)}`} />
      ))}
    </div>
  );
}

function ImpactCalloutLayer({ events, enabled, reducedMotion }: { events: ImpactSparkEvent[]; enabled: boolean; reducedMotion: boolean }) {
  if (!enabled || events.length === 0) return null;
  const callouts = events.slice(-5).map((event) => {
    const label = resolveImpactCalloutLabel(event);
    return label ? { event, label } : null;
  }).filter((entry): entry is { event: ImpactSparkEvent; label: string } => Boolean(entry));
  if (callouts.length === 0) return null;
  return (
    <div className={`impact-callout-layer${reducedMotion ? ' reduced-motion' : ''}`} aria-hidden="true">
      {callouts.map(({ event, label }) => (
        <div key={`impact-callout-${event.id}`} className={`impact-callout ${resolveImpactFeedbackTone(event)}`}>
          {label}
        </div>
      ))}
    </div>
  );
}

function resolveImpactCalloutLabel(event: ImpactSparkEvent) {
  if (/guard\s*break/i.test(event.moveLabel)) return 'GUARD BREAK';
  if (event.kind === 'counterHit') return 'COUNTER';
  if (event.kind === 'whiffPunish') return 'WHIFF PUNISH';
  if (event.kind === 'punish') return 'PUNISH';
  if (event.kind === 'clash') return 'CLASH';
  return '';
}

function resolveImpactFeedbackTone(event: ImpactSparkEvent) {
  if (/guard\s*break/i.test(event.moveLabel) || event.kind === 'clash' || event.kiBurst) return 'blue';
  if (event.kind === 'block') return 'guard';
  if (event.kind === 'counterHit') return 'red';
  if (event.kind === 'punish' || event.kind === 'whiffPunish') return 'purple';
  return 'gold';
}

function CombatPopupLayer({ popups }: { popups: ActiveCombatPopup[] }) {
  const leftPopups = popups.filter((popup) => popup.slot === 1);
  const rightPopups = popups.filter((popup) => popup.slot === 2);
  return (
    <div className="combat-popup-layer" aria-live="polite">
      <div className="combat-popup-column left">
        {leftPopups.map((popup) => (
          <CombatPopupCard key={popup.uid} popup={popup} />
        ))}
      </div>
      <div className="combat-popup-column right">
        {rightPopups.map((popup) => (
          <CombatPopupCard key={popup.uid} popup={popup} />
        ))}
      </div>
    </div>
  );
}

function CombatPopupCard({ popup }: { popup: ActiveCombatPopup }) {
  const displayedHits = popup.contactHits ?? popup.hits;
  const punishLabel = popup.kind === 'whiffPunish' ? 'Whiff Punish' : popup.kind === 'punish' ? 'Punish' : '';
  const counterHitLabel = popup.kind === 'counterHit' ? 'Counter Hit' : '';
  const clashLabel =
    popup.kind === 'clashPerfect' ? 'Clash Perfect' :
    popup.kind === 'clashWin' ? 'Clash Win' :
    popup.kind === 'clashDraw' ? 'Clash Draw' :
    '';
  return (
    <div className={`combat-popup-card ${popup.kind}`}>
      {clashLabel ? (
        <>
          <div className="punish-line">{clashLabel}</div>
          {popup.damage > 0 && (
            <div className="damage-line">
              <strong>{Math.round(popup.damage)}</strong>
              <span>Damage</span>
            </div>
          )}
        </>
      ) : displayedHits >= 2 && (
        <>
          <div className="combo-line">
            <strong>{displayedHits}</strong>
            <span>Hit Combo</span>
          </div>
          <div className="damage-line">
            <strong>{Math.round(popup.damage)}</strong>
            <span>Damage</span>
          </div>
        </>
      )}
      {counterHitLabel && !clashLabel && <div className="punish-line counter-hit-line">{counterHitLabel}</div>}
      {punishLabel && !clashLabel && <div className="punish-line">{punishLabel}</div>}
      <small>{popup.moveLabel}</small>
    </div>
  );
}

function HealthBar({ fighter, align, displayName, onlineWins }: { fighter: MatchSnapshot['fighters'][number]; align: 'left' | 'right'; displayName: string; onlineWins?: number }) {
  const isInfiniteHealth = fighter.maxHp >= 999_999;
  const percent = isInfiniteHealth ? 100 : Math.max(0, Math.min(100, (fighter.hp / Math.max(1, fighter.maxHp)) * 100));
  const recoverablePercent = isInfiniteHealth ? 0 : Math.max(0, Math.min(100, ((fighter.hp + fighter.displayRecoverableHp) / Math.max(1, fighter.maxHp)) * 100));
  const kiPercent = Math.max(0, Math.min(100, fighter.displayKi));
  const transformPercent = Math.max(0, Math.min(100, fighter.displayTransformOvercharge));
  const transformReady = fighter.transformReadyTimer > 0 && transformPercent > 0;
  const isDanger = percent <= 25;
  const hasRecoverable = recoverablePercent > percent + 0.1;
  const portrait = getHudPortraitSource(fighter.character);
  return (
    <div
      className={`health ${align} ${isDanger ? 'danger' : ''} ${hasRecoverable ? 'has-recoverable' : ''} ${fighter.recoverableFlashFrames > 0 ? 'recoverable-flash' : ''}`}
      data-testid={`fighter-hud-${align}`}
    >
      <div className="health-surface">
        <div className="hud-portrait" aria-hidden="true">
          {portrait.path ? (
            <HudPortraitImage portrait={portrait} align={align} />
          ) : <span>{fighter.character.displayName.slice(0, 2).toUpperCase()}</span>}
        </div>
        <div className="health-label">
          <strong data-testid={`fighter-name-${align}`}>{displayName}</strong>
        </div>
        <div className="health-track" data-testid={`fighter-health-${align}`}>
          <span className="recoverable-health-fill" style={{ width: `${recoverablePercent}%` }} />
          <span className="current-health-fill" style={{ width: `${percent}%` }} />
        </div>
        <div
          className={`ki-track ${transformPercent > 0 ? 'has-transform-charge' : ''} ${transformReady ? 'transform-ready' : ''}`}
          aria-label={`${fighter.character.displayName} ki`}
          data-testid={`fighter-ki-${align}`}
        >
          <span className="ki-fill" style={{ width: `${kiPercent}%` }} />
          <span className="ki-transform-fill" style={{ width: `${transformPercent}%` }} />
        </div>
        <img className="health-shell-art" src="/ui/fight-hud/fighter-shell.png" alt="" aria-hidden="true" />
      </div>
      <div className="round-pips" aria-label={`${fighter.character.displayName} rounds won`}>
        {Array.from({ length: fighter.roundsWon }, (_, pip) => (
          <span key={pip} className="won" />
        ))}
      </div>
      {onlineWins !== undefined && onlineWins > 0 && <div className="online-wins">WINS: {onlineWins}</div>}
    </div>
  );
}

function getHudPortraitSource(character: MatchSnapshot['fighters'][number]['character']) {
  const framePath = character.animationFrames?.idle?.[0] || character.animationFrames?.walkForward?.[0];
  if (framePath) return { path: framePath, kind: 'frame' as const };
  if (character.faceCardPath) return { path: character.faceCardPath, kind: 'face-card' as const };
  if (character.spriteSheetPath) return { path: character.spriteSheetPath, kind: 'sprite-sheet' as const };
  return { path: '', kind: 'initials' as const };
}

const hudPortraitCropCache = new Map<string, string>();

function HudPortraitImage({ portrait, align }: { portrait: ReturnType<typeof getHudPortraitSource>; align: 'left' | 'right' }) {
  const [source, setSource] = useState(() => hudPortraitCropCache.get(portrait.path) ?? portrait.path);
  useEffect(() => {
    setSource(hudPortraitCropCache.get(portrait.path) ?? portrait.path);
  }, [portrait.path]);
  const cropVisiblePixels = useCallback((event: React.SyntheticEvent<HTMLImageElement>) => {
    if (portrait.kind !== 'frame' || source !== portrait.path) return;
    const cropped = cropHudPortraitToVisiblePixels(event.currentTarget);
    if (!cropped) return;
    hudPortraitCropCache.set(portrait.path, cropped);
    setSource(cropped);
  }, [portrait.kind, portrait.path, source]);
  return (
    <img
      className={`hud-portrait-image ${portrait.kind}`}
      src={source}
      alt=""
      onLoad={cropVisiblePixels}
      data-testid={`fighter-portrait-${align}`}
      data-portrait-source={portrait.kind}
      data-portrait-original-src={portrait.path}
    />
  );
}

function cropHudPortraitToVisiblePixels(image: HTMLImageElement) {
  const width = image.naturalWidth;
  const height = image.naturalHeight;
  if (width <= 0 || height <= 0) return null;
  const sourceCanvas = document.createElement('canvas');
  sourceCanvas.width = width;
  sourceCanvas.height = height;
  const sourceContext = sourceCanvas.getContext('2d', { willReadFrequently: true });
  if (!sourceContext) return null;
  try {
    sourceContext.drawImage(image, 0, 0);
    const pixels = sourceContext.getImageData(0, 0, width, height).data;
    let left = width;
    let top = height;
    let right = -1;
    let bottom = -1;
    for (let y = 0; y < height; y += 1) {
      for (let x = 0; x < width; x += 1) {
        if (pixels[(y * width + x) * 4 + 3] <= 8) continue;
        left = Math.min(left, x);
        top = Math.min(top, y);
        right = Math.max(right, x);
        bottom = Math.max(bottom, y);
      }
    }
    if (right < left || bottom < top || (left === 0 && top === 0 && right === width - 1 && bottom === height - 1)) return null;
    const croppedWidth = right - left + 1;
    const croppedHeight = bottom - top + 1;
    const cropCanvas = document.createElement('canvas');
    cropCanvas.width = croppedWidth;
    cropCanvas.height = croppedHeight;
    const cropContext = cropCanvas.getContext('2d');
    if (!cropContext) return null;
    cropContext.imageSmoothingEnabled = false;
    cropContext.drawImage(image, left, top, croppedWidth, croppedHeight, 0, 0, croppedWidth, croppedHeight);
    return cropCanvas.toDataURL('image/png');
  } catch {
    return null;
  }
}

function FooterActions({
  onBack,
  middleAction,
  onNext,
  nextLabel,
  nextDisabled = false
}: {
  onBack: () => void;
  middleAction?: {
    label: string;
    icon: ReactNode;
    className?: string;
    onClick: () => void;
  };
  onNext: () => void;
  nextLabel: string;
  nextDisabled?: boolean;
}) {
  return (
    <footer className="footer-actions arcade-footer-actions">
      <button className="secondary-button" onClick={onBack}>
        <Home size={18} />
        Back
      </button>
      {middleAction && (
        <button className={`secondary-button ${middleAction.className ?? ''}`} onClick={middleAction.onClick}>
          {middleAction.icon}
          {middleAction.label}
        </button>
      )}
      <button className="primary-button" onClick={onNext} disabled={nextDisabled}>
        <Play size={18} />
        {nextLabel}
      </button>
    </footer>
  );
}
